import { MSG_OAP_SHOW_RESULTS_VIEW, MSG_START_OAP_SCAN } from "@/app/scripts/app-consts";
import { CompletedScan, ScanStore } from "@/app/scripts/oap/scan-store";
import { OAPRecommendation, ScanResults, ScanType } from "@/app/scripts/oap/types";
import { sendBackgroundMessage } from "@/utils/messaging/messaging";
import { ShowResultsViewResponse, ShowResultsViewRequest, StartScanRequest, StartScanResponse } from "@/utils/messaging/types";

export const startGoogleScan = async (): Promise<boolean> => {
  const resp = await sendBackgroundMessage<StartScanRequest, StartScanResponse>(
    { type: MSG_START_OAP_SCAN, payload: { scanType: "google" } }
  );
  return resp.payload?.success ?? false;
};

export type RecentActivity = {
  scan: CompletedScan;
  title: string;
  description: string;
}

export const buildRecentActivity = async (): Promise<RecentActivity[]> => {
  const scanStore = new ScanStore();
  const scans = await scanStore.getScans();

  const recentActivity: RecentActivity[] = [];
  for (const scan of scans) {
    if (scan.scanType === "google") {
      recentActivity.push({
        scan,
        title: "Google scan completed",
        description: "Check report and recommendation of the scan.",
      });
    }
  }

  return recentActivity;
}

export const showResultsViewForActivity = async (scan: CompletedScan) => {
  const resp = await sendBackgroundMessage<ShowResultsViewRequest, ShowResultsViewResponse>(
    { type: MSG_OAP_SHOW_RESULTS_VIEW, payload: { scan } }
  );
  return resp.payload?.success ?? false;
}