/* global chrome */

// Chrome storage integration utilities for site protections
import { SiteProtections, SiteProtectionSettings, DEFAULT_SITE_PROTECTION_SETTINGS } from '$Popup/store/types';

export const PROTECTION_STORAGE_KEYS = {
    SITE_PROTECTIONS: 'siteProtections', // Per-site protection settings
} as const;
import { chrome } from "@/utils/polyfill";

/**
 * Save site protections to Chrome storage
 */
export const saveSiteProtections = async (protections: SiteProtections): Promise<void> => {
    try {
        await chrome.storage.local.set({
            [PROTECTION_STORAGE_KEYS.SITE_PROTECTIONS]: protections
        });
    } catch (error) {
        console.error('Error saving site protections:', error);
        throw error;
    }
};

/**
 * Load site protections from Chrome storage
 */
export const loadSiteProtections = async (): Promise<SiteProtections> => {
    try {
        const result = await chrome.storage.local.get([PROTECTION_STORAGE_KEYS.SITE_PROTECTIONS]);
        return result[PROTECTION_STORAGE_KEYS.SITE_PROTECTIONS] || {};
    } catch (error) {
        console.error('Error loading site protections:', error);
        return {};
    }
};

/**
 * Toggle specific protection for a hostname
 */
export const toggleSiteProtection = async (
    hostname: string,
    protectionType: keyof SiteProtectionSettings
): Promise<boolean> => {
    try {
        const protections = await loadSiteProtections();

        // Initialize site protections if they don't exist
        if (!protections[hostname]) {
            protections[hostname] = { ...DEFAULT_SITE_PROTECTION_SETTINGS };
        }

        // Toggle the specific protection type
        const newProtectionState = !protections[hostname][protectionType];
        protections[hostname][protectionType] = newProtectionState;

        await saveSiteProtections(protections);
        return newProtectionState;
    } catch (error) {
        console.error(`Error toggling site protection ${protectionType} for ${hostname}:`, error);
        throw error;
    }
};

/**
 * Check if a specific protection is enabled for a site
 */
export const isSiteProtected = async (
    hostname: string,
    protectionType: keyof SiteProtectionSettings
): Promise<boolean> => {
    try {
        const protections = await loadSiteProtections();
        return protections[hostname]?.[protectionType] ?? DEFAULT_SITE_PROTECTION_SETTINGS[protectionType];
    } catch (error) {
        console.error(`Error checking site protection ${protectionType} for ${hostname}:`, error);
        return DEFAULT_SITE_PROTECTION_SETTINGS[protectionType];
    }
};

/**
 * Get all protection settings for a site
 */
export const getSiteProtections = async (hostname: string): Promise<SiteProtectionSettings> => {
    try {
        const protections = await loadSiteProtections();
        return protections[hostname] || DEFAULT_SITE_PROTECTION_SETTINGS;
    } catch (error) {
        console.error(`Error getting site protections for ${hostname}:`, error);
        return DEFAULT_SITE_PROTECTION_SETTINGS;
    }
};

/**
 * Clear all site protections
 */
export const clearAllSiteProtections = async (): Promise<void> => {
    try {
        await chrome.storage.local.remove([PROTECTION_STORAGE_KEYS.SITE_PROTECTIONS]);
    } catch (error) {
        console.error('Error clearing all site protections:', error);
        throw error;
    }
};