import React from 'react';
import { cn } from '$Popup/lib/utils';
import BGSvgIcon from '../BGSvgIcon';
import { Card } from '$Popup/components/core';

type BGBannerVariant = 'highrisk' | 'lowrisk' | 'error' | 'info'; // leaving room for more variants for the future

interface BGBannerProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: BGBannerVariant;
  iconClassName?: string;
}

const variantToBgClass: Record<BGBannerVariant, string> = {
  highrisk: 'dark:bg-liteblue bg-[#FCDEDE]',
  lowrisk: 'dark:bg-liteblue bg-[#FFEFDB]',
  info: 'dark:bg-liteblue bg-white',
  error: 'dark:bg-liteblue bg-red',
};

const variantToIconName: Record<BGBannerVariant, string> = {
  highrisk: 'warning',
  lowrisk: 'yellow-warning',
  info: 'info',
  error: 'red-x',
};

const BGBanner: React.FC<BGBannerProps> = ({
  variant = 'info',
  className = '',
  iconClassName = '',
  children,
  ...props
}) => {
  const bgClass = variantToBgClass[variant];
  const iconName = variantToIconName[variant];

  return (
    <Card
      className={cn('flex flex-row gap-2 w-full py-4 px-8', bgClass, className)}
      {...props}
    >
      <BGSvgIcon
        isNeutral={false}
        iconName={iconName}
        size={30}
        className={iconClassName}
      />
      <div data-testid="div-0f7f37fa"  className="text-sm">{children}</div>
    </Card>
  );
};

export default BGBanner;
