import React, { useCallback } from 'react';
import { BGModal } from '$Popup/components/core/BGModal';
import {
    ProductInfo,
    UpdateButton,
    ResourceLinks,
    ActionButtons,
    TelemetryToggle,
    LegalLinks,
    FactoryResetModal
} from './components';
import { useSupportData, useSupportActions } from './hooks';
import { t } from '$Popup/i18n';
export interface SupportModalProps {
    isOpen: boolean;
    onClose: () => void;
}

/**
 * Support Modal Component
 * 
 * A modernized version of the legacy support component with the same functionality
 * but built using React and modern patterns. Includes:
 * - Product information and version display
 * - Database update functionality
 * - Debug log download
 * - Factory reset
 * - Telemetry consent toggle
 * - Resource links
 */
export const SupportModal: React.FC<SupportModalProps> = ({ isOpen, onClose }) => {
    const { version, isLoading, showTelemetryToggle } = useSupportData();
    const {
        updateState,
        resetModalOpen,
        downloadLogs,
        checkForUpdates,
        factoryReset,
        setResetModalOpen,
        resetState
    } = useSupportActions();

    // Handle modal close with state reset
    const handleClose = useCallback(() => {
        resetState();
        onClose();
    }, [resetState, onClose]);

    return (
        <BGModal
            isOpen={isOpen}
            onClose={handleClose}
            className="max-w-xl"
        >
            <div data-testid="div-8c5489d1"  className="support-container">
                {/** centered title */}
                <div data-testid="div-02b9f7f2"  className='w-full flex items-center justify-center mt-6 mb-8'>
                    <h3 data-testid="h3-1a7743b4" >{t('supportTxt')}</h3>
                </div>
                {/* Top Section: Product Info & Update Button */}
                <div data-testid="div-f907be9a"  className="flex justify-between items-start">
                    <ProductInfo version={version} isLoading={isLoading} />
                    <UpdateButton
                        updateState={updateState}
                        onUpdate={checkForUpdates}
                    />
                </div>

                <hr className="border-t border-tragic-border-250 my-6"></hr>

                {/* Middle Section: Resource Links & Legal */}
                <div data-testid="div-f4ad55a3"  className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <ResourceLinks />
                    <LegalLinks />
                </div>

                <hr className="border-t border-tragic-border-250 my-6"></hr>

                {/* Bottom Section: Actions & Settings */}
                <div data-testid="div-b8d9974d"  className="flex justify-between items-start gap-8">
                    <ActionButtons
                        onDownloadLogs={downloadLogs}
                        onFactoryReset={() => setResetModalOpen(true)}
                    />
                    {showTelemetryToggle && <TelemetryToggle />}
                </div>

                {/* Copyright */}
                <div data-testid="div-7dc6b59d"  className="mt-5 mb-4 text-start">
                    <span data-testid="span-26580857"  className="text-tragic-400 text-sm font-normal">
                        {t('supportCopyrightText')}
                    </span>
                </div>

                {/* Factory Reset Confirmation Modal */}
                <FactoryResetModal
                    isOpen={resetModalOpen}
                    onClose={() => setResetModalOpen(false)}
                    onConfirm={factoryReset}
                />
            </div>
        </BGModal>
    );
};

export default SupportModal;
