import * as React from 'react'
import useEmblaCarousel, {
  type UseEmblaCarouselType,
} from 'embla-carousel-react'
import { EmblaCarouselType } from 'embla-carousel'
import { t } from "$Popup/i18n";
import Button from '../BGButton'
import { BGSvgIcon } from '$Popup/components/core'
import { cn } from '$Popup/lib/utils'

type CarouselApi = UseEmblaCarouselType[1]
type UseCarouselParameters = Parameters<typeof useEmblaCarousel>
type CarouselOptions = UseCarouselParameters[0]
type CarouselPlugin = UseCarouselParameters[1]

type CarouselProps = {
  opts?: CarouselOptions
  plugins?: CarouselPlugin
  setApi?: (api: CarouselApi) => void
}

type CarouselContextProps = {
  carouselRef: ReturnType<typeof useEmblaCarousel>[0]
  api: ReturnType<typeof useEmblaCarousel>[1]
  scrollPrev: () => void
  scrollNext: () => void
  canScrollPrev: boolean
  canScrollNext: boolean
  selectedIndex: number
  scrollSnaps: number[]
} & CarouselProps

const CarouselContext = React.createContext<CarouselContextProps | null>(null)

function useCarousel() {
  const context = React.useContext(CarouselContext)

  if (!context) {
    throw new Error('useCarousel must be used within a <Carousel />')
  }

  return context
}

// Convenience hook to access current slide index and total slides
function useCarouselIndex() {
  const context = useCarousel()
  return {
    selectedIndex: context.selectedIndex,
    totalSlides: context.scrollSnaps.length,
  }
}

// Controls hook to advance/retreat or jump to a slide
function useCarouselControls() {
  const context = useCarousel()
  const scrollTo = React.useCallback(
    (index: number) => {
      context.api?.scrollTo(index)
    },
    [context.api]
  )
  return {
    scrollNext: context.scrollNext,
    scrollPrev: context.scrollPrev,
    canScrollNext: context.canScrollNext,
    canScrollPrev: context.canScrollPrev,
    scrollTo,
  }
}

function Carousel({
  opts,
  setApi,
  plugins,
  className,
  children,
  ...props
}: React.ComponentProps<'div'> & CarouselProps) {
  const [carouselRef, api] = useEmblaCarousel(
    {
      ...opts,
    },
    plugins
  )
  const [canScrollPrev, setCanScrollPrev] = React.useState(false)
  const [canScrollNext, setCanScrollNext] = React.useState(false)
  const [selectedIndex, setSelectedIndex] = React.useState(0)
  const [scrollSnaps, setScrollSnaps] = React.useState<number[]>([])

  const onSelect = React.useCallback((api: CarouselApi) => {
    if (!api) return
    setCanScrollPrev(api.canScrollPrev())
    setCanScrollNext(api.canScrollNext())
    // embla api has selectedScrollSnap on EmblaCarouselType; cast to access
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const embla = api as unknown as any
    if (embla && typeof embla.selectedScrollSnap === 'function') {
      setSelectedIndex(embla.selectedScrollSnap())
    }
  }, [])

  const scrollPrev = React.useCallback(() => {
    api?.scrollPrev()
  }, [api])

  const scrollNext = React.useCallback(() => {
    api?.scrollNext()
  }, [api])

  const handleKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === 'ArrowLeft') {
        event.preventDefault()
        scrollPrev()
      } else if (event.key === 'ArrowRight') {
        event.preventDefault()
        scrollNext()
      }
    },
    [scrollPrev, scrollNext]
  )

  React.useEffect(() => {
    if (!api || !setApi) return
    setApi(api)
  }, [api, setApi])

  React.useEffect(() => {
    if (!api) return
    onSelect(api)
    api.on('reInit', onSelect)
    api.on('select', onSelect)
    // Initialize scroll snaps list when api is ready
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const embla = api as unknown as any
    if (embla && typeof embla.scrollSnapList === 'function') {
      setScrollSnaps(embla.scrollSnapList())
    }

    return () => {
      api?.off('select', onSelect)
    }
  }, [api, onSelect])

  return (
    <CarouselContext.Provider
      value={{
        carouselRef,
        api: api,
        opts,
        scrollPrev,
        scrollNext,
        canScrollPrev,
        canScrollNext,
        selectedIndex,
        scrollSnaps,
      }}
    >
      <div data-testid="div-38a4b68c" 
        onKeyDownCapture={handleKeyDown}
        className={cn('relative', className)}
        role="region"
        aria-roledescription="carousel"
        data-slot="carousel"
        {...props}
      >
        {children}
      </div>
    </CarouselContext.Provider>
  )
}

const NavigationFooter = ({ 
  onComplete, 
  completeButtonText = "Complete" 
}: { 
  onComplete?: () => void
  completeButtonText?: string 
} = {}) => {
  const { selectedIndex, totalSlides } = useCarouselIndex()
  if (selectedIndex < 1) return null
  
  const isLastSlide = selectedIndex === totalSlides - 1
  
  return (
    <div data-testid="div-bd0a06f2"  className="flex flex-row w-full items-center justify-between mt-4 min-h-9">
      <CarouselPrevious />
      {isLastSlide && onComplete ? (
        <button data-testid="button-88b469ae" 
          onClick={onComplete}
          className="bg-primary text-sm font-medium hover:bg-primary-hover text-backdrop flex justify-center px-7 py-2 rounded-full"
        >
          {completeButtonText}
        </button>
      ) : (
        <CarouselNext />
      )}
    </div>
  )
}

function CarouselContent({ 
  className, 
  onComplete,
  completeButtonText,
  ...props 
}: React.ComponentProps<'div'> & {
  onComplete?: () => void
  completeButtonText?: string
}) {
  const { carouselRef } = useCarousel()

  return (
    <div data-testid="div-ce62ce54" 
      ref={carouselRef}
      className="overflow-hidden"
      data-slot="carousel-content"
    >
      <div data-testid="div-a523935f"  className={cn('flex', className)} {...props} />
      <NavigationFooter onComplete={onComplete} completeButtonText={completeButtonText} />
    </div>
  )
}

function CarouselItem({ className, ...props }: React.ComponentProps<'div'>) {
  const { selectedIndex } = useCarouselIndex()
  return (
    <div data-testid="div-7a3dd29c" 
      role="group"
      aria-roledescription="slide"
      data-slot="carousel-item"
      className={cn('shrink-0 grow-0 basis-full', className, {
        'max-h-112': selectedIndex === 1,
        'max-h-92': selectedIndex > 1,
      })}
      {...props}
    />
  )
}

function CarouselPrevious({
  className,
  variant = 'tertiary',
  size = 'small',
  ...props
}: React.ComponentProps<typeof Button>) {
  const { scrollPrev, canScrollPrev } = useCarousel()

  return (
    <Button
      data-slot="carousel-previous"
      variant={variant}
      size={size}
      className={cn('flex justify-start size-8 rounded-full', className)}
      disabled={!canScrollPrev}
      onClick={scrollPrev}
      {...props}
    >
      <BGSvgIcon iconName="back-arrow" forceFill='primary' size={16} />
      <span data-testid="span-833eb1b0" >{t("backBtnText")}</span>
    </Button>
  )
}

function CarouselNext({
  className,
  variant = 'tertiary',
  size = 'small',
  ...props
}: React.ComponentProps<typeof Button>) {
  const { scrollNext, canScrollNext } = useCarousel()

  return (
    <Button
      data-slot="carousel-next"
      variant={variant}
      size={size}
      className={cn('size-8 rounded-full flex justify-end', className)}
      disabled={!canScrollNext}
      onClick={scrollNext}
      {...props}
    >
      <span data-testid="span-ca46dc4a" >{t("nextBtnText")}</span>
      <BGSvgIcon iconName="next-arrow" size={16} />
    </Button>
  )
}

export {
  type CarouselApi,
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselPrevious,
  CarouselNext,
  useCarouselIndex,
  useCarouselControls,
}

export { default as CarouselStepper } from './CarouselStepper'

// Dot navigation (pagination)
type UseDotButtonType = {
  selectedIndex: number
  scrollSnaps: number[]
  onDotButtonClick: (index: number) => void
}

function useDotButton(
  emblaApi: EmblaCarouselType | undefined
): UseDotButtonType {
  const [selectedIndex, setSelectedIndex] = React.useState(0)
  const [scrollSnaps, setScrollSnaps] = React.useState<number[]>([])

  const onDotButtonClick = React.useCallback(
    (index: number) => {
      if (!emblaApi) return
      emblaApi.scrollTo(index)
    },
    [emblaApi]
  )

  const onInit = React.useCallback((api: EmblaCarouselType) => {
    setScrollSnaps(api.scrollSnapList())
  }, [])

  const onSelect = React.useCallback((api: EmblaCarouselType) => {
    setSelectedIndex(api.selectedScrollSnap())
  }, [])

  React.useEffect(() => {
    if (!emblaApi) return
    onInit(emblaApi)
    onSelect(emblaApi)
    emblaApi.on('reInit', onInit)
    emblaApi.on('reInit', onSelect)
    emblaApi.on('select', onSelect)

    return () => {
      emblaApi.off('select', onSelect)
      emblaApi.off('reInit', onInit)
      emblaApi.off('reInit', onSelect)
    }
  }, [emblaApi, onInit, onSelect])

  return {
    selectedIndex,
    scrollSnaps,
    onDotButtonClick,
  }
}

type DotButtonProps = React.ComponentPropsWithRef<'button'>

function DotButton({ children, className, ...restProps }: DotButtonProps) {
  return (
    <button data-testid="button-ef214131"  type="button" className={className} {...restProps}>
      {children}
    </button>
  )
}

function CarouselDots({ className }: { className?: string }) {
  const { api } = useCarousel()
  const { selectedIndex, scrollSnaps, onDotButtonClick } = useDotButton(api)

  return (
    <div data-testid="div-eecc8821"  className={cn('flex items-center justify-center gap-2', className)}>
      {scrollSnaps.map((_, index) => {
        const isActive = index === selectedIndex
        return (
          <DotButton
            key={index}
            data-testid={`carousel-dot-button-${index}`}
            aria-label={`Go to slide ${index + 1}`}
            aria-current={isActive}
            onClick={() => onDotButtonClick(index)}
            className={cn(
              'h-2 w-2 rounded-full transition-colors',
              isActive ? 'bg-primary' : 'bg-tragic-300'
            )}
          />
        )
      })}
    </div>
  )
}

export { CarouselDots, DotButton }
