import React from 'react'
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom'

import Dashboard from '$Popup/views/Dashboard'
import Settings from '$Popup/views/Settings'
import DashboardPage from '@/app/popup/src/views/DashboardPage'
import AllowList from '$Popup/views/AllowList'
import DetectionHistory from '../views/DetectionHistory'
import OAP from '$Popup/views/OAP';
import NotFoundPage from '$Popup/views/NotFound'
import FullProtection from '$Popup/views/FullProtection'
import ContentControl from '$Popup/views/ContentControl'
import ManualAdRemoval from '$Popup/views/ManualAdRemoval'
import ProductInformation from '$Popup/views/ProductInformation'
import { isTabContext } from '$Popup/utils/contextDetection'
import ImportExport from '$Popup/views/ImportExport'
import ContentControlBlock from '$Popup/views/ContentControlBlock';
import { ROUTES } from './constants'
import { useDocumentTitle } from './hooks'

// Layout components
import { AppLayout } from '$Popup/components/Layout'
import PageLayout from '$Popup/components/Layout/PageLayout'
import BlockPage from '$Popup/views/BlockPage'

/**
 * Main Router Configuration for Hash-based SPA
 *
 * Using HashRouter for browser extension compatibility with hash-based routing.
 * URLs will be: chrome-extension://[id]/app/popup/index.html#/route
 */

// Component that protects Dashboard from being accessed in tab context
const ProtectedDashboard: React.FC = () => {

  // If accessed in tab context, redirect to Dashboard instead
  if (isTabContext()) {
    return <Navigate to={ROUTES.DASHBOARD.path} replace />
  }

  return <Dashboard />
}

// Component that handles initial access control and document title
const AccessControl: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const [isReady, setIsReady] = React.useState(false)
  
  // Update document title based on current route
  useDocumentTitle()

  React.useEffect(() => {
    const initializeAccess = () => {
      setIsReady(true)
    }

    initializeAccess()
  }, [])

  if (!isReady) {
    return (
      <div data-testid="div-a9bf54bd"  className="flex items-center justify-center h-full">
        Router Loading...
      </div>
    )
  }

  return <>{children}</>
}

// Main Router Component
const AppRouter: React.FC = () => {
  return (
    <HashRouter>
      <AccessControl>
        <Routes>

          {/* Popup route (no layout) - protected from tab context */}
          <Route path="/" element={<ProtectedDashboard />} />

          { /* Page routes (only topbar) */ }
          <Route path="/*" element={<PageLayout />}>
            <Route path={ROUTES.CONTENT_CONTROL_BLOCK.path} element={<ContentControlBlock />} />
            <Route path={ROUTES.BLOCK_PAGE.path} element={<BlockPage />} />
          </Route>                 

          {/* Routes that use AppLayout (topbar + left menu) */}
          <Route path="/*" element={<AppLayout />}>
            <Route path={ROUTES.MANUAL_AD_REMOVALS.path} element={<ManualAdRemoval />} />
            <Route path={ROUTES.SETTINGS.path} element={<Settings />} />
            <Route path={ROUTES.DASHBOARD.path} element={<DashboardPage />} />
            <Route path={ROUTES.ALLOW_LIST.path} element={<AllowList />} />
            <Route path={ROUTES.DETECTION_HISTORY.path} element={<DetectionHistory />} />
            <Route path={ROUTES.DETECTION_HISTORY.path} element={<DetectionHistory />} />
            <Route path={ROUTES.FULL_PROTECTION.path} element={<FullProtection />} />
            <Route path={ROUTES.CONTENT_CONTROL.path} element={<ContentControl />} />
            <Route path={ROUTES.BLOCK_PAGE.path} element={<BlockPage />} />
            <Route path={ROUTES.PRODUCT_INFORMATION.path} element={<ProductInformation />} />

            <Route path={ROUTES.IMPORT_AND_EXPORT.path} element={<ImportExport />} />            
            <Route path={ROUTES.PROFILE_CHECKER.path} element={<OAP />} />

            {/* Catch-all route for 404s (within layout) */}
            <Route path="*" element={<NotFoundPage />} />

          </Route>
        </Routes>
      </AccessControl>
    </HashRouter>
  )
}

export default AppRouter
