import { useEffect, useState } from 'react';
import { useExtensionStore } from '$Popup/store';
import { sendBackgroundMessage } from '@/utils/messaging/messaging';
import { MSG_CONTENT_CONTROL_GET_ALL } from '@/app/scripts/app-consts';
import { usePremiumStatus, useOperatingSystem } from '$Popup/utils/general';
import { calculateProtectionStatus, generateProtectionItems } from './utils';

/**
 * Custom hook for managing protection status data and logic
 */
export const useProtectionStatus = () => {
    // Get protection settings from store
    const enableProtectionAds = useExtensionStore((state) => state.enableProtectionAds);
    const enableProtectionMalware = useExtensionStore((state) => state.enableProtectionMalware);
    const enableProtectionScams = useExtensionStore((state) => state.enableProtectionScams);
    const loadGeneralSettings = useExtensionStore((state) => state.loadGeneralSettings);

    // Use the premium status hook
    const { isPremium } = usePremiumStatus();
    
    // Use the operating system hook
    const { os } = useOperatingSystem();
    
    // State for content control data
    const [hasContentControlData, setHasContentControlData] = useState(false);

    // Check content control data
    const checkContentControlData = async () => {
        try {
            const response = await sendBackgroundMessage<void, string[]>({
                type: MSG_CONTENT_CONTROL_GET_ALL
            });

            if (response.error) {
                console.error("Failed to get content control data:", response.error);
                setHasContentControlData(false);
            } else {
                console.debug("Content control data:", response.success);
                setHasContentControlData(response.success && response.success.length > 0);
            }
        } catch (error) {
            console.error("Error checking content control data:", error);
            setHasContentControlData(false);
        }
    };

    // Protection states array
    const protectionStates = [
        enableProtectionAds,
        enableProtectionMalware,
        enableProtectionScams
    ];

    // Load settings and check content control data on mount
    useEffect(() => {
        loadGeneralSettings();
        checkContentControlData();
    }, []);

    // Calculate derived data (recalculates when dependencies change)
    const protectionStatus = calculateProtectionStatus(protectionStates);
    const protectionItems = generateProtectionItems(protectionStates, isPremium, hasContentControlData, os);

    return {
        protectionStatus,
        protectionItems,
        isPremium,
        hasContentControlData
    };
};
