import * as React from 'react'
import ConfirmModal from '$Popup/components/common/ConfirmModal'
import { t } from '$Popup/i18n'

interface DeleteDetectionConfirmModalProps {
  isOpen: boolean
  onClose: () => void
  onConfirm: () => void
  loading?: boolean
  detectionSite?: string
}

const DeleteDetectionConfirmModal: React.FC<
  DeleteDetectionConfirmModalProps
> = ({ isOpen, onClose, onConfirm, loading = false, detectionSite }) => {
  const isDeleteAll = detectionSite === 'ALL_DETECTIONS'

  return (
    <ConfirmModal
      isOpen={isOpen}
      onClose={onClose}
      onConfirm={onConfirm}
      loading={loading}
      title={isDeleteAll ? 'Delete All Detection History' : 'Delete Detection'}
      description={
        isDeleteAll
          ? 'Are you sure you want to delete all detection history? This action cannot be undone.'
          : `Are you sure you want to delete this detection entry${
              detectionSite ? ` for ${detectionSite}` : ''
            }? This action cannot be undone.`
      }
      cancelLabel={t('Cancel')}
      confirmLabel={isDeleteAll ? 'Delete All' : 'Delete'}
      loadingLabel={isDeleteAll ? 'Deleting All...' : 'Deleting...'}
      confirmButtonClassName="bg-primary text-backdrop hover:bg-primary-hover"
    />
  )
}

export default DeleteDetectionConfirmModal
