import React, { useState, useEffect } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import BGContextMenu, { MenuButton } from '$Popup/components/core/BGContextMenu';
import { BGLink } from '$Popup/components/core/BGLink';
import { t } from '$Popup/i18n';
import { useOperatingSystem } from '$Popup/utils/general';
import type { ChartData, StatCard, StatCategory, TimeRange, ChartPoint } from './types';
import { ROUTES } from '$Popup/routes/constants';
import { Card } from '$Popup/components/core/BGCard';
import { TIME_RANGES, STAT_CARDS, DEFAULT_TIME_RANGE, DEFAULT_CATEGORY } from './constants';
import { formatNumber, getChartOptions, generateChartData } from './utils';
import { fetchStatisticsData } from './hooks';
import { StatCardComponent, ErrorState, LoadingState } from './components';

// Register Chart.js components
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

/**
 * OverviewChart Component - Statistics dashboard with Chart.js
 */
const OverviewChart: React.FC = () => {
  // State management
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [chartData, setChartData] = useState<ChartPoint[]>([]);
  const [totalStats, setTotalStats] = useState<ChartData>({ ads: 0, malwares: 0, scams: 0, content: 0 });
  const [isPremium, setIsPremium] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<StatCategory>(DEFAULT_CATEGORY);
  const [selectedTimeRange, setSelectedTimeRange] = useState<TimeRange>(DEFAULT_TIME_RANGE);

  // Use the operating system hook
  const { os } = useOperatingSystem();

  // Data fetching function
  const loadStatisticsData = async (timeRange: TimeRange) => {
    setIsLoading(true);
    setError(null);

    try {
      const result = await fetchStatisticsData(timeRange);
      setIsPremium(result.isPremium);
      setTotalStats(result.totalStats);
      setChartData(result.chartData);
    } catch (err) {
      console.error('Error fetching statistics data:', err);
      setError(err instanceof Error ? err.message : 'Failed to load statistics data');
    } finally {
      setIsLoading(false);
    }
  };

  // Generate stat cards with OS filtering
  const filteredStatCards = STAT_CARDS.filter((config) => {
    // If showOs is defined, only show the item if current OS is in the allowed list
    if (config.showOs && config.showOs.length > 0) {
      return config.showOs.includes(os);
    }
    // If no showOs restriction, always show the item
    return true;
  });

  // Ensure selected category is available (fallback to first available if current is filtered out)
  const availableCategories = filteredStatCards.map(config => config.key);
  const effectiveSelectedCategory = availableCategories.includes(selectedCategory) 
    ? selectedCategory 
    : availableCategories[0] || DEFAULT_CATEGORY;

  // Generate the final stat cards
  const statCards: StatCard[] = filteredStatCards.map(config => ({
    key: config.key,
    label: t(config.labelKey),
    iconName: config.iconName,
    value: formatNumber(totalStats[config.key]),
    isSelected: effectiveSelectedCategory === config.key,
    isLocked: config.key === 'content' && !isPremium
  }));

  // Check if all main protection stats are zero
  const hasNoStatsData = totalStats.ads === 0 && totalStats.malwares === 0 && totalStats.scams === 0;

  // Get chart configuration and data
  const chartOptions = getChartOptions();
  const selectedCard = statCards.find(card => card.key === effectiveSelectedCategory);
  const chartDataConfig = generateChartData(chartData, effectiveSelectedCategory, selectedCard?.label || 'Blocked');

  // Load data when time range changes
  useEffect(() => {
    loadStatisticsData(selectedTimeRange);
  }, [selectedTimeRange]);

  // Error state with retry functionality
  if (error) {
    return <ErrorState onRetry={() => loadStatisticsData(selectedTimeRange)} />;
  }

  return (
    <Card className='flex flex-col gap-6'>

      <div data-testid="div-01ac9f1c"  className="flex justify-between items-center">
        <h2 data-testid="h2-6044c955"  className="text-xl font-medium text-tragic">{t('statisticsTitle')}</h2>
        {/* Time Range Dropdown */}
        <div data-testid="div-979f70fb"  className={hasNoStatsData ? 'pointer-events-none' : ''}>
          <BGContextMenu
            trigger={
              <button data-testid="button-1ae8e21d"  
                className={`flex items-center space-x-1 px-3 py-2 text-sm font-medium text-primary ${
                  hasNoStatsData 
                    ? 'opacity-50' 
                    : 'hover:underline'
                }`}
              >
                <span data-testid="span-04601a72" >{t(TIME_RANGES[selectedTimeRange].label)}</span>
                <BGSvgIcon iconName="right-arrow" size={19} className="rotate-90" forceFill="primary" />
              </button>
            }
            menuClassName="w-32"
          >
            {Object.entries(TIME_RANGES).map(([key, config]) => (
              <MenuButton
                key={key}
                onClick={hasNoStatsData ? undefined : () => setSelectedTimeRange(key as TimeRange)}
                className={`text-xs ${selectedTimeRange === key ? 'bg-primary-100' : ''}`}
              >
                {t(config.label)}
              </MenuButton>
            ))}
          </BGContextMenu>
        </div>
      </div>

      {/* Loading State */}
      {isLoading && <LoadingState />}

      {/* Chart and Stats */}
      {!isLoading && (
        <>
          {/* Chart */}
          <div data-testid="div-481b3f03"  className="relative flex items-center justify-center min-h-64">
            {hasNoStatsData ? (
              <div data-testid="div-841d4ed9"  className="flex flex-col items-center justify-between text-center
              border rounded-xl border-rounded border-tragic-200
              py-12 px-44 gap-6 bg-backdrop dark:bg-tragic-100
              w-full h-fit">
                <h3 data-testid="h3-089228cb"  className="text-xl font-medium text-tragic">
                  {t('NoStatsYetHeader')}
                </h3>
                <BGSvgIcon iconName="empty-graph" size={180} />
                <p data-testid="p-5750b2d5"  className="text-tragic-400 text-base">
                  {t('NoStatsYetDesc')}
                </p>
              </div>
            ) : (
              <Line data={chartDataConfig} options={chartOptions} />
            )}
          </div>

          {/* Stat Cards - using extracted component for better performance */}
          {
            !hasNoStatsData && (
              <div data-testid="div-94f96c61"  className="grid grid-cols-4 gap-4">
                {statCards.map((card) => (
                  <StatCardComponent
                    key={card.key}
                    card={card}
                    onSelect={(category) => {
                      if (category === 'content' && card.isLocked) return;
                      setSelectedCategory(category);
                    }}
                  />
                ))}
              </div>
            )
          }
          

          {/* See All Activity Link */}
          {isPremium && (
            <div data-testid="div-dee6af7b"  className="flex justify-center">
              <BGLink
                to={hasNoStatsData ? undefined : ROUTES.DETECTION_HISTORY.name}
                className={`flex items-center space-x-1 text-primary ${
                  hasNoStatsData 
                    ? 'opacity-50 cursor-not-allowed' 
                    : 'hover:underline'
                }`}
                onClick={hasNoStatsData ? (e) => e.preventDefault() : undefined}
              >
                <span data-testid="span-b3218676"  className="text-sm font-medium">{t('SeeAllActivityBtn')}</span>
                <BGSvgIcon iconName="right-arrow" forceFill="primary" size={19} />
              </BGLink>
            </div>
          )}
        </>
      )}
    </Card>
  );
};

export default OverviewChart;
