import * as React from "react";
import type { ProtectionOption } from "./types";
import { t } from "$Popup/i18n";

interface ProtectionSelectorProps {
  options: ProtectionOption[];
  onToggle: (optionId: string) => void;
  disabled?: boolean;
}

export const ProtectionSelector: React.FC<ProtectionSelectorProps> = ({ 
  options, 
  onToggle, 
  disabled = false 
}) => {
  return (
    <div data-testid="div-a34cb9c4"  className="flex flex-col space-y-3">
      <h4 data-testid="h4-a8e95344"  className="text-sm font-normal text-tragic-400">
        {t("ProtectionAllowOptions")}
      </h4>
      <div data-testid="div-316aa449"  className="flex flex-wrap gap-2" id="protection-selector">
        {options.map((option, index) => (
          <button data-testid={`button-0d6d2b17-${index}`}
            key={option.id}
            onClick={() => onToggle(option.id)}
            disabled={disabled}
            className={`px-4 py-2 rounded-full text-sm font-normal transition-colors ${
              option.selected
                ? 'bg-primary text-backdrop border-primary'
                : 'bg-tragic-200 text-tragic hover:bg-tragic-300'
            }`}
          >
            {option.label}
          </button>
        ))}
      </div>
    </div>
  );
};
