import React, { useState, useRef, useEffect, useCallback } from 'react';
import { MenuButton } from '$Popup/components/core/BGContextMenu';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import { BGLink } from '$Popup/components/core';
import { createPortal } from 'react-dom';
import { displayReleaseNotification } from "@/content-scripts/content-notifications.js";
import { RELEASE_NOTIFICATION_NOTES_MV3 } from '@/app/scripts/app-consts.js';
import { HeaderMenuProps, HeaderMenuItem, HeaderSubmenuItem, MenuAction } from './types';
import { headerMenuItems, filterMenuItems } from './config';
import { useNotify } from '$Popup/components/BGNotification';
import { chrome } from "@/utils/polyfill";
import { viewTutorialHandler } from '$Popup/utils/general'
import { closePopupCurrentWindow } from '$Popup/utils/general';

// Constants
const SUBMENU_WIDTH = 200;
const MIN_LEFT_POSITION = 8;
const BUTTON_CLASSES = "text-tragic flex flex-row justify-between w-full py-2 px-3 text-xs rounded-lg transition-colors text-left hover:bg-tragic-200";

/**
 * HeaderMenu - Navigation menu for the extension header
 */
const HeaderMenu: React.FC<HeaderMenuProps> = ({ isPremium = false, currentOs }) => {
    const [showShareSubmenu, setShowShareSubmenu] = useState(false);
    const [submenuPosition, setSubmenuPosition] = useState({ top: 0, left: 0 });
    const [activeSubmenuId, setActiveSubmenuId] = useState<string | null>(null);
    const shareButtonRef = useRef<HTMLButtonElement>(null);
    const submenuRef = useRef<HTMLDivElement>(null);
    const notify = useNotify();

    // Get filtered menu items based on OS compatibility only
    const menuItems = filterMenuItems(
        headerMenuItems,
        currentOs ? [currentOs] : undefined
    );

    // Handle menu actions - fully self-contained
    const handleMenuAction = useCallback(async (action: MenuAction) => {
      if (action === 'whats-new') {
        displayReleaseNotification(RELEASE_NOTIFICATION_NOTES_MV3)
      } else if (action === 'view-tutorial') {
        await viewTutorialHandler()
      }
      // No external callback needed - component handles its own actions
    }, [])

    // Close submenu when clicking outside
    useEffect(() => {
        if (!showShareSubmenu) return;

        const handleClickOutside = (event: MouseEvent) => {
            const target = event.target as Node;
            const isOutsideSubmenu = submenuRef.current && !submenuRef.current.contains(target);
            const isOutsideButton = shareButtonRef.current && !shareButtonRef.current.contains(target);

            if (isOutsideSubmenu && isOutsideButton) {
                setShowShareSubmenu(false);
                setActiveSubmenuId(null);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [showShareSubmenu]);

    // Handle submenu button click
    const handleSubmenuClick = useCallback((menuItem: HeaderMenuItem) => {
        if (menuItem.type !== 'submenu' || !menuItem.submenuItems || !shareButtonRef.current) return;

        const isCurrentlyOpen = activeSubmenuId === menuItem.id;

        if (!isCurrentlyOpen) {
            const buttonRect = shareButtonRef.current.getBoundingClientRect();
            const leftPosition = buttonRect.left - SUBMENU_WIDTH;

            setSubmenuPosition({
                top: buttonRect.top,
                left: Math.max(MIN_LEFT_POSITION, leftPosition)
            });
        }

        setActiveSubmenuId(isCurrentlyOpen ? null : menuItem.id);
        setShowShareSubmenu(!isCurrentlyOpen);
    }, [activeSubmenuId]);

    // Handle copy to clipboard
    const handleSubmenuItemClick = useCallback(async (submenuItem: HeaderSubmenuItem) => {
        if (submenuItem.id === 'copy-link') {
            try {
                await navigator.clipboard.writeText(submenuItem.href);
                handleMenuAction('copy-link');
                notify.success(
                    '',
                    `Share link copied to clipboard.`,
                    { duration: 1500 }
                );
            } catch {
                // Fallback for older browsers
                const textArea = document.createElement('textarea');
                textArea.value = submenuItem.href;
                document.body.appendChild(textArea);
                textArea.select();
                document.execCommand('copy');
                document.body.removeChild(textArea);
                handleMenuAction('copy-link');
            }
        }
        setShowShareSubmenu(false);
        setActiveSubmenuId(null);
    }, [handleMenuAction]);

    // Handle external link opening
    const handleExternalLink = useCallback(async (href: string) => {
        // Close submenu first
        setShowShareSubmenu(false);
        setActiveSubmenuId(null);

        // Small delay to ensure menu state is updated
        await new Promise(resolve => setTimeout(resolve, 100));

        try {
            // Method 1: Use chrome.tabs.create if available (for extensions)
            if (typeof chrome !== 'undefined' && chrome.tabs && chrome.tabs.create) {
                chrome.tabs.create({ url: href });
            } else {
                // Method 2: Use window.open as fallback
                window.open(href, '_blank', 'noopener,noreferrer');
            }
        } catch (error) {
            // Method 3: Create a temporary anchor and click it
            const tempLink = document.createElement('a');
            tempLink.href = href;
            tempLink.target = '_blank';
            tempLink.rel = 'noopener noreferrer';
            tempLink.style.display = 'none';
            document.body.appendChild(tempLink);
            tempLink.click();
            document.body.removeChild(tempLink);
        }
    }, []);

    // Render submenu item (link or button based on type)
    const renderSubmenuItem = (submenuItem: HeaderSubmenuItem) => {
        if (submenuItem.isExternal) {
            return (
                <button data-testid="button-6a979638" 
                    key={submenuItem.id}
                    type="button"
                    className={BUTTON_CLASSES}
                    onClick={(e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        // Cast to native event to access stopImmediatePropagation
                        (e.nativeEvent as Event).stopImmediatePropagation?.();
                        handleExternalLink(submenuItem.href);
                    }}
                    onMouseDown={(e) => {
                        e.stopPropagation();
                    }}
                >
                    <span data-testid="span-435b8617" >{submenuItem.label}</span>
                </button>
            );
        }

        // Copy link button
        return (
            <button data-testid="button-29cb777f" 
                key={submenuItem.id}
                type="button"
                className={BUTTON_CLASSES}
                onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    (e.nativeEvent as Event).stopImmediatePropagation?.();
                    handleSubmenuItemClick(submenuItem);
                }}
                onMouseDown={(e) => {
                    e.stopPropagation();
                }}
            >
                <span data-testid="span-2bbc74ac" >{submenuItem.label}</span>
            </button>
        );
    };

    // Render menu item based on type
    const renderMenuItem = (menuItem: HeaderMenuItem) => {
        switch (menuItem.type) {
            case 'action':
                return (
                    <MenuButton
                        key={menuItem.id}
                        className={BUTTON_CLASSES}
                        onClick={() => menuItem.action && handleMenuAction(menuItem.action as MenuAction)}
                    >
                        <span data-testid="span-e4e0242c" >{menuItem.label}</span>
                    </MenuButton>
                );

            case 'link':
                // Handle both internal routing and external links
                if (menuItem.href) {
                    return (
                        <a data-testid="a-7096f81f" 
                            key={menuItem.id}
                            href={menuItem.href}
                            target={menuItem.target}
                            rel={menuItem.rel}
                            className={BUTTON_CLASSES}
                        >
                            <span data-testid="span-aa9e1c23" >{menuItem.label}</span>
                        </a>
                    );
                } else {
                    return (
                        <BGLink
                            key={menuItem.id}
                            to={menuItem.path as any}
                            target={menuItem.target}
                            rel={menuItem.rel}
                            className={BUTTON_CLASSES}
                            queryParams={menuItem?.queryParams}
                            onClick={closePopupCurrentWindow}
                        >
                            <span data-testid="span-4bcc3070" >{menuItem.label} </span>
                            {menuItem.isPremium && !isPremium && (
                                <BGSvgIcon
                                    iconName="yellow-lock"
                                    size={23}
                                />
                            )}
                        </BGLink>
                    );
                }

            case 'submenu':
                return (
                    <button data-testid="button-dbb90007" 
                        key={menuItem.id}
                        ref={menuItem.id === 'share-extension' ? shareButtonRef : undefined}
                        type="button"
                        className={BUTTON_CLASSES}
                        onClick={(e) => {
                            e.stopPropagation();
                            handleSubmenuClick(menuItem);
                        }}
                    >
                        <div data-testid="div-d9cb23eb"  className="flex items-center justify-between w-full">
                            <span data-testid="span-437a02ca" >{menuItem.label}</span>
                            {menuItem.icon && (
                                <span data-testid="span-4d621dda"  className={`text-tragic-400 transition-transform duration-200 ${activeSubmenuId === menuItem.id ? 'rotate-90' : ''}`}>
                                    <BGSvgIcon iconName={menuItem.icon} size={18} />
                                </span>
                            )}
                        </div>
                    </button>
                );

            default:
                return null;
        }
    };

    return (
        <div data-testid="div-6301d2c3" >
            {/* Render all menu items from configuration */}
            {menuItems.map(renderMenuItem)}

            {/* Share Submenu Portal */}
            {showShareSubmenu && activeSubmenuId && createPortal(
                <div data-testid="div-33eced32" 
                    ref={submenuRef}
                    className="fixed z-50 w-48 bg-backdrop border border-tragic-200 rounded-lg shadow-lg p-2"
                    style={{
                        top: `${submenuPosition.top}px`,
                        left: `${submenuPosition.left}px`,
                    }}
                    onClick={(e) => e.stopPropagation()}
                >
                    {(() => {
                        const activeMenuItem = menuItems.find(item => item.id === activeSubmenuId);
                        return activeMenuItem?.submenuItems?.map(renderSubmenuItem) || [];
                    })()}
                </div>,
                document.body
            )}
        </div>
    );
};

export default HeaderMenu;
