import * as React from "react";

interface ErrorMessageProps {
  error: string;
}

export const ErrorMessage: React.FC<ErrorMessageProps> = ({ error }) => {
  if (!error) return null;

  return (
    <div data-testid="div-65249ba9"  className="p-3 bg-danger-100 border border-danger-200 rounded-lg">
      <p data-testid="p-b90be493"  className="text-danger text-sm">{error}</p>
    </div>
  );
};
