import React from 'react';
import { t } from '$Popup/i18n';

interface ActionButtonsProps {
  onCancel: () => void;
  onSubmit: () => void;
  canSubmit: boolean;
  loading: boolean;
}

export const ActionButtons: React.FC<ActionButtonsProps> = ({
  onCancel,
  onSubmit,
  canSubmit,
  loading
}) => {
  return (
    <div data-testid="div-bc8a980a"  className="flex justify-end gap-3 pt-2">
      <button data-testid="button-4047cf5c" 
        onClick={onCancel}
        disabled={loading}
        className="px-6 py-2 text-sm font-medium text-primary border border-primary rounded-4xl hover:bg-tragic-100 transition-colors disabled:opacity-50"
      >
        {t("Cancel")}
      </button>
      
      <button data-testid="button-49cb8344" 
        onClick={onSubmit}
        disabled={!canSubmit || loading}
        className={`px-6 py-2 text-sm font-medium rounded-4xl transition-colors disabled:opacity-50 disabled:cursor-not-allowed ${
          loading
            ? 'bg-tragic-300 text-backdrop'
            : canSubmit
              ? 'bg-primary text-backdrop hover:bg-primary-hover'
              : 'bg-tragic-200 text-tragic-400'
        }`}
      >
        {loading ? (
          <span data-testid="span-39bba1ad"  className="flex items-center">
            <span data-testid="span-3fec2424"  className="animate-spin mr-2">⏳</span>
            {t("Adding")}...
          </span>
        ) : (
          t("AddToList")
        )}
      </button>
    </div>
  );
};
