import * as React from "react";
import { DataTable, TableEmptyState } from "$Popup/components/core/BGTable";
import DeleteConfirmModal from "../DeleteConfirmModal";
import { useContentControlData, useDeleteOperations } from "./hooks";
import { createColumns } from "./columns";
import type { ContentControlTableProps } from "./types";
import { t } from "$Popup/i18n";

const ContentControlTable: React.FC<ContentControlTableProps> = ({ refreshKey }) => {
  const { websites, loading, setWebsites } = useContentControlData(refreshKey);
  const { deleteModal, openDeleteModal, openDeleteAllModal, closeDeleteModal, confirmDelete } = 
    useDeleteOperations(websites, setWebsites);

  const columns = createColumns(websites, openDeleteModal, openDeleteAllModal);

  if (loading) {
    return (
      <div data-testid="div-8764ff61"  className="flex justify-center items-center py-8">
        <span data-testid="span-a9f2fba4" >{t("Loading")}</span>
      </div>
    );
  }

  return (
    <>
      <div data-testid="div-bf3dee5a"  className="w-full">
        <DataTable 
          columns={columns} 
          data={websites} 
          emptyState={
            <TableEmptyState 
              title={t("NoBlockedWebsites")}
              description={t("NoBlockedWebsitesDesc")}
            />
          }
          enableSearch={true}
          searchPlaceholder={t("SearchDomainsPlaceholder")+'...'}
        />
      </div>

      <DeleteConfirmModal
        isOpen={deleteModal.isOpen}
        onClose={closeDeleteModal}
        onConfirm={confirmDelete}
        loading={deleteModal.isDeleting}
        websiteDomain={deleteModal.websiteToDelete?.domain}
      />
    </>
  );
};

export default ContentControlTable;
