import React, { useEffect, useMemo, useState, useCallback } from "react";
import BGToggle from '$Popup/components/core/BGToggle';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import BGTooltip from '@/app/popup/src/components/core/BGTooltip';
import BGContextMenu from '@/app/popup/src/components/core/BGContextMenu';
import BlockedItemMenu from './BlockedItemMenu';
import { useToggleSiteProtection, useSiteProtections, useLoadSiteProtections } from '$Popup/store';
import { DEFAULT_SITE_PROTECTION_SETTINGS } from '$Popup/store/types';
import { useSettingsToggles } from '$Popup/views/Settings/hooks/useSettingsToggles';
import { ToggleId } from '$Popup/views/Settings/types';
import { useNotify } from '$Popup/components/BGNotification';
import {
  FALLBACK_HOSTNAME,
  processBlockedData,
  createProtectionLayerCrads
} from './logic';
import { getCurrentTabData, refreshCurrentTab } from '$Popup/utils/tabData';
import { BlockedItem, TabType } from './types';
import { t } from '$Popup/i18n';

interface DashboardTabProps {
  isValidTab: boolean;
}

const DashboardTab: React.FC<DashboardTabProps> = ({ isValidTab }) => {
  const [activeTab, setActiveTab] = useState<TabType>("protection");
  const [currentHostname, setCurrentHostname] = useState<string>(FALLBACK_HOSTNAME);
  const [blockedItems, setBlockedItems] = useState<BlockedItem[]>([]);
  const [totalBlockedItems, setTotalBlockedItems] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(false);

  // Empty state message for blocked items
  const tabBtnClasses = 'py-2 w-1/2 text-center text-xs font-semibold transition-all';
  const tabSelectedBtnClasses = 'bg-primary-dashboard-tab-bg text-primary-dashboard-tab-text shadow-sm rounded-lg';

  // Use individual hook selectors
  const toggleSiteProtection = useToggleSiteProtection();
  const siteProtections = useSiteProtections();
  const loadSiteProtections = useLoadSiteProtections();
  const { getToggleValue } = useSettingsToggles();
  const notify = useNotify();

  // Unified data loading function
  const loadAllData = useCallback(async (defaultTab?: TabType) => {
    setIsLoading(true);
    try {
      // Get current tab data
      const tabData = await getCurrentTabData();
      const hostname = tabData?.host || FALLBACK_HOSTNAME;
      setCurrentHostname(hostname);

      // Process blocked data if available
      if (tabData?.blocked) {
        const result = await processBlockedData(tabData.blocked, hostname);
        setBlockedItems(result.blockedItems);
        setTotalBlockedItems(result.totalBlockedItems);
      } else {
        setBlockedItems([]);
        setTotalBlockedItems(0);
      }

      // Load site protections if hostname is valid
      if (hostname !== FALLBACK_HOSTNAME) {
        await loadSiteProtections(hostname);
      }

      // Only set active tab if explicitly requested
      if (defaultTab) {
        setActiveTab(defaultTab);
      }
      // Otherwise keep current activeTab
    } catch (error) {
      console.error('Failed to load dashboard data:', error);
    } finally {
      setIsLoading(false);
    }
  }, [loadSiteProtections]);

  // Initial data load on mount
  useEffect(() => {
    loadAllData("protection"); // Set initial tab to protection
  }, [loadAllData]);

  // Get current site protections or use defaults
  const currentSiteProtections = useMemo(() =>
    siteProtections[currentHostname] || DEFAULT_SITE_PROTECTION_SETTINGS,
    [siteProtections, currentHostname]
  );

  const TAB_RELOAD_TIMEOUT_MS = 1000;

  // Special refresh for blocked item actions (refreshes browser tab first)
  const handleRefreshWithTabReload = useCallback(async () => {
    try {
      // First refresh the browser tab
      await refreshCurrentTab();
      // Then reload data after a brief delay
      setTimeout(() => {
        loadAllData(); // Keep current tab, reload data
      }, TAB_RELOAD_TIMEOUT_MS); // Give browser tab time to reload
    } catch (error) {
      console.error('Failed to refresh tab:', error);
      // Fallback: just reload data without tab refresh
      await loadAllData();
    }
  }, [loadAllData]);

  // Create refresh function that only reloads blocked data, not site protections
  const handleRefreshBlockedDataOnly = useCallback(async () => {
    try {
      // First refresh the browser tab
      await refreshCurrentTab();
      // Then reload only tab data (blocked items) after a brief delay
      setTimeout(async () => {
        const tabData = await getCurrentTabData();
        const hostname = tabData?.host || FALLBACK_HOSTNAME;
        setCurrentHostname(hostname);

        // Process blocked data if available
        if (tabData?.blocked) {
          const result = await processBlockedData(tabData.blocked, hostname);
          setBlockedItems(result.blockedItems);
          setTotalBlockedItems(result.totalBlockedItems);
        } else {
          setBlockedItems([]);
          setTotalBlockedItems(0);
        }
      }, TAB_RELOAD_TIMEOUT_MS); // Give browser tab time to reload
    } catch (error) {
      console.error('Failed to refresh blocked data:', error);
    }
  }, []);

  // Create toggle handlers with data refresh
  const toggleHandlers = useMemo(() => {
    return {
      ads: async () => {
        if (!getToggleValue(ToggleId.enableProtectionAds) || !getToggleValue(ToggleId.enableProtection)) {
          notify.danger('Error: ', t('globalAdProtectionDisabled'));
          return;
        }
        await toggleSiteProtection(currentHostname, 'ads');
        await handleRefreshBlockedDataOnly(); // Only refresh blocked data, not site protections
      },
      malware: async () => {
        if (!getToggleValue(ToggleId.enableProtectionMalware) || !getToggleValue(ToggleId.enableProtection)) {
          notify.danger('Error: ', t('globalMalwareProtectionDisabled'));
          return;
        }
        await toggleSiteProtection(currentHostname, 'malware');
        await handleRefreshBlockedDataOnly(); // Only refresh blocked data, not site protections
      },
      scams: async () => {
        if (!getToggleValue(ToggleId.enableProtectionScams) || !getToggleValue(ToggleId.enableProtection)) {
          notify.danger('Error: ', t('globalScamProtectionDisabled'));
          return;
        }
        await toggleSiteProtection(currentHostname, 'scams');
        await handleRefreshBlockedDataOnly(); // Only refresh blocked data, not site protections
      }
    };
  }, [toggleSiteProtection, currentHostname, handleRefreshBlockedDataOnly, getToggleValue, notify]);

  // Protection layer configuration - optimized with stable references
  const protectionLayerCards = useMemo(() =>
    createProtectionLayerCrads(currentSiteProtections, toggleHandlers),
    [currentSiteProtections, toggleHandlers]
  );

  // Simple tab handlers
  const changeTab = (tab: TabType) => {
    setActiveTab(tab);
  }

  // Show loading state while data is being fetched
  if (isLoading) {
    return (
      <div data-testid="div-02e4e12b"  className="DashboardTab w-full mx-auto bg-transparent">
        <div data-testid="div-985c0ce2"  className="flex justify-center items-center h-32">
          <div data-testid="div-b08ed209"  className="text-tragic-400 text-sm">Loading site data...</div>
        </div>
      </div>
    );
  }

  return (
    <div data-testid="div-b3d2a123"  className="DashboardTab w-full mx-auto bg-transparent">
      {/* Tabs */}
      <div data-testid="div-1abb44d5"  className="h-7 flex justify-center">
        <div data-testid="div-decc284a"  className="w-1/2 flex justify-center bg-tragic-100 h-fit rounded-md">
          <button data-testid="button-d27c0ccd" 
            className={`${tabBtnClasses} ${activeTab === "protection"
              ? tabSelectedBtnClasses
              : "text-tragic-400"
              }`}
            onClick={changeTab.bind(null, "protection")}
          >
            {t('protectionLabel')}
          </button>
          <button data-testid="button-7796b078" 
            className={`${tabBtnClasses} ${activeTab === "blocked"
              ? tabSelectedBtnClasses
              : "text-tragic-400"
              }`}
            onClick={changeTab.bind(null, "blocked")}
          >
            {t('blockedItemsCountLabel')}: {totalBlockedItems}
          </button>
        </div>
      </div>

      {/* Tab Panels */}
      <div data-testid="div-7a175acf"  className="bg-transparent px-2 py-2">
        {activeTab === "protection" ? (
          <div data-testid="div-a958d9a5" >
            <p data-testid="p-15685b60"  className="text-center m-auto w-9/12 text-xs text-tragic mt-5 mb-3">
              {isValidTab ? (
                <span data-testid="span-c496b6f1"  dangerouslySetInnerHTML={{ __html: t('siteSettingsFor', [currentHostname]) }} />
              ) : (
                <>{t('currentWebsiteSystemPage')}</>
              )}
            </p>
            {/*Toggle Cards */}
            <div data-testid="div-fa4e2f2e"  className={`flex gap-4 justify-center ${!isValidTab ? 'grayscale cursor-not-allowed opacity-70' : ''}`}>

              {/* Loop over protectionLayerCards and print the cards */}
              {protectionLayerCards.map((layer, index) => (
                <div data-testid={`div-edd37aa6-${index}`} key={`protection-${layer.name}`} className="flex-1 w-1/3 rounded-2xl border border-tragic-200 p-3 flex flex-col items-start gap-2">
                  <BGSvgIcon iconName={layer.iconName} size={34} isActive={isValidTab ? layer.checked : false} />
                  <div data-testid="div-f1210dfd"  className="font-semibold text-sm text-tragic">{layer.name}</div>
                  <div data-testid="div-628a10e1"  className="text-xs font-normal text-tragic-400 flex-1">
                    {layer.description}
                  </div>
                  <div data-testid="div-8e41d350"  className="mt-2">
                    <BGToggle
                      checked={isValidTab ? layer.checked : false}
                      onChange={isValidTab ? layer.onChange : () => { }}
                      aria-label={`Toggle ${layer.name} protection for ${currentHostname}`}
                      disabled={!isValidTab}
                    />
                  </div>
                </div>
              ))}

            </div>
          </div>
        ) : (
          <div data-testid="div-f22cd572" >
            <p data-testid="p-ced5e701"  className="text-center m-auto w-9/12 text-xs text-tragic my-5">
              {isValidTab ? (
                <span data-testid="span-fc9a7d7b"  dangerouslySetInnerHTML={{ __html: t('blockedItemsOn', [currentHostname]) }} />
              ) : (
                <>{t('currentWebsiteSystemPage')}</>
              )}
            </p>
            {/* List */}
            <div data-testid="div-c1ca54b3"  className={`overflow-y-auto h-40 px-6 ${!isValidTab ? 'bg-tragic-100 rounded-xl' : ''}`}>
              {blockedItems.length > 0 ? (
                blockedItems.map((item, index) => (
                  <div data-testid={`div-8c130c60-${index}`} className="flex items-center py-2 text-xs h-8 border-t border-tragic-border-250 hover:bg-tragic-100" key={`${item.domain}-${item.type}`}>
                    <span data-testid="span-480ed059"  className={`w-5 text-left mr-2 font-medium ${item.isDangerous ? "text-danger" : "text-tragic-400"}`}>
                      {item.count}
                    </span>
                    <span data-testid="span-71c4be10" 
                      className={
                        item.isDangerous
                          ? "text-danger text-xs font-medium flex items-center gap-1"
                          : "text-tragic"
                      }
                    >
                      {item.isDangerous && <BGSvgIcon iconName="red-bug" size={14} />}
                      {t(item.domain)}
                    </span>
                    <div data-testid="div-d10b6436"  className="flex-1" />
                    {/* Action icons */}
                    <BGTooltip
                      content={Boolean(item.count) ? 'Blocked' : 'Allowed'}
                      bgColorClass="bg-tragic-400"
                      textColorClass="text-backdrop-200"
                      position="top"
                      usePortal={true}
                    >
                      <div data-testid="div-2f72d4e6"  className="mr-2 cursor-pointer" aria-label={`${Boolean(item.count) ? 'Block' : 'Allow'} ${item.domain}`}>
                        <BGSvgIcon iconName={Boolean(item.count) ? "block" : "allow"} size={13} />
                      </div>
                    </BGTooltip>
                    <BGContextMenu
                      trigger={
                        <button data-testid="button-d1acbca3" 
                          aria-label={`More options for ${item.domain}`}
                          className="flex items-center"
                        >
                          <BGSvgIcon iconName="kebab-menu" size={16} />
                        </button>
                      }
                    >
                      <BlockedItemMenu
                        item={item}
                        currentHostname={currentHostname}
                        onRefresh={handleRefreshWithTabReload}
                      />
                    </BGContextMenu>
                  </div>
                ))
              ) : (
                <div data-testid="div-f8d7b364"  className="flex justify-center items-center h-full">
                  {isValidTab ?
                    <div data-testid="div-9eb567e7"  className="flex flex-col justify-center items-center">
                      <BGSvgIcon iconName="no-detection-cloud" size={320} />
                      <p data-testid="p-88de708c"  className="text-tragic-400 text-sm -mt-7">
                        {t('emptyBlockedItemsMessage')}
                      </p>
                    </div>
                    :
                    <div data-testid="div-0e764208"  className="flex flex-col justify-center items-center gap-4">
                      <BGSvgIcon iconName="info" size={27} />
                      <p data-testid="p-ea6e47c2"  className="text-tragic-400 text-sm">
                        {t('invalidPageForEvaluationMessage')}
                      </p>
                    </div>}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// Add display name for better debugging
DashboardTab.displayName = 'DashboardTab';

export default DashboardTab;