import React, { useState, useCallback, useEffect, useMemo } from 'react';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import { MenuItem, LeftSidebarProps } from './types';
import { menuSections, findItemByPath, findSectionByItemId } from './config';
import { filterMenuSectionsByFeatureFlags, filterMenuSectionsByLanguage, filterMenuSectionsByOS } from './utils';
import { useAppNavigation } from '$Popup/routes/hooks';
import { useFeatureFlags, useOperatingSystem, usePremiumStatus } from '$Popup/utils/general';
import { uiLanguage } from '@/utils/locales';

/**
 * LeftSidebar Component
 * 
 * Main navigation sidebar for the application.
 * Contains menu sections, navigation items, and collapsible groups.
 */

const LeftSidebar: React.FC<LeftSidebarProps> = ({ className = '' }) => {
  const { location, navigate } = useAppNavigation();
  const { os, isLoading: isOSLoading } = useOperatingSystem();
  const { isPremium, isPremiumLoading } = usePremiumStatus();
  const { flagValues, loading: featureFlagsLoading } = useFeatureFlags();

  // Filter menu sections based on current OS
  const filteredMenuSections = useMemo(() => {
    if (isOSLoading) return menuSections; // Show all items while detecting OS
    let items = filterMenuSectionsByOS(menuSections, os);
    items = filterMenuSectionsByLanguage(items, uiLanguage);
    items = filterMenuSectionsByFeatureFlags(items, flagValues);
    return items;
  }, [os, isOSLoading, flagValues, featureFlagsLoading]);

  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    'browser-guard': true,
    'online-account-protection': true,
  });
  const [selectedItemId, setSelectedItemId] = useState<string>('');

  // Update selected item when location changes
  useEffect(() => {
    const activeItemId = findItemByPath(filteredMenuSections, location.pathname);
    setSelectedItemId(activeItemId);

    // Auto-expand section containing the active item
    if (activeItemId) {
      const sectionId = findSectionByItemId(filteredMenuSections, activeItemId);
      if (sectionId) {
        setExpandedSections(prev => ({
          ...prev,
          [sectionId]: true
        }));
      }
    }
  }, [location.pathname, filteredMenuSections]); // Include filteredMenuSections in dependencies

  // Memoized handlers to prevent unnecessary re-renders
  const toggleSection = useCallback((sectionId: string) => {
    setExpandedSections(prev => ({
      ...prev,
      [sectionId]: !prev[sectionId]
    }));
  }, []);

  const handleItemClick = useCallback((item: MenuItem) => {
    if (item.path) {
      setSelectedItemId(item.id);
      navigate(`/${item.path}`);
    }
  }, [navigate]);

  const isItemActive = useCallback((item: MenuItem) => {
    return selectedItemId === item.id;
  }, [selectedItemId]);

  return (
    <aside data-testid="aside-09bd8e6a"  className={`left-sidebar h-full overflow-y-auto scrollbar-thin scrollbar-thumb-tragic-200 scrollbar-track-transparent ${className}`}>
      <nav data-testid="nav-df18858d"  className="py-4 px-3 h-full">
        {filteredMenuSections.map((section, index) => (
          <div data-testid={`div-b3e83bd0-${index}`} key={section.id} className="mb-4">
            {/* Section Header */}
            <button data-testid="button-40d3e5d5" 
              className="w-full flex items-center justify-between p-2 hover:bg-primary-100 rounded-lg transition-colors group"
              onClick={() => toggleSection(section.id)}
              aria-expanded={expandedSections[section.id]}
              aria-controls={`section-${section.id}`}
            >
              <div data-testid="div-711c42e2"  className="flex items-center gap-3">
                <BGSvgIcon
                  iconName={section.icon}
                  size={16}
                />
                <span data-testid="span-b03ac417"  className="text-sm font-semibold text-tragic-400">
                  {section.label}
                </span>
              </div>

              {section.isCollapsible && (
                <BGSvgIcon
                  iconName="chevron-up"
                  size={20}
                  className={`transition-transform ${expandedSections[section.id] ? '' : 'rotate-180'
                    }`}
                />
              )}
            </button>

            {/* Section Items */}
            {expandedSections[section.id] && (
              <div data-testid="div-b7c4c88b"  id={`section-${section.id}`} className="mt-2 space-y-1">
                {section.items.map((item, index) => (
                  <button data-testid={`button-dc385d7a-${index}`}
                    key={item.id}
                    className={`pl-9 w-full flex items-center justify-between p-2 rounded-lg text-left transition-colors ${isItemActive(item)
                      ? 'bg-primary-100 text-tragic font-medium'
                      : 'hover:bg-tragic-100 text-tragic-400 hover:text-tragic font-normal'
                      }`}
                    onClick={() => handleItemClick(item)}
                    aria-current={isItemActive(item) ? 'page' : undefined}
                  >
                    <div data-testid="div-303da42f"  className="flex items-center gap-3">
                      {item.icon && (
                        <BGSvgIcon
                          iconName={item.icon}
                          size={14}
                        />
                      )}
                      <span data-testid="span-9bd43fee"  className="text-sm">
                        {item.label}
                      </span>
                    </div>

                    <div data-testid="div-3a3e8ceb"  className="flex items-center gap-2">
                      {item.badge && (
                        <span data-testid="span-23032c42"  className="bg-success-100 text-success text-xs px-2 py-0.5 rounded-full font-semibold">
                          {item.badge}
                        </span>
                      )}
                      {(item.isPremium && !isPremium && !isPremiumLoading) && (
                        <BGSvgIcon
                          iconName="yellow-lock"
                          size={26}
                        />
                      )}
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}
      </nav>
    </aside>
  );
};

export default LeftSidebar;
