import React from "react";
import { ToggleProps } from './types';

/**
 * Toggle - A simple toggle switch component
 * 
 * This component renders a toggle switch that can be checked or unchecked.
 * It supports custom styling, accessibility features, and disabled state.
 * 
 * Usage:
 * <Toggle checked={isChecked} onChange={setChecked} />
 */

const Toggle: React.FC<ToggleProps> = ({
    id,
    checked,
    onChange,
    disabled = false,
    className = "",
    ariaLabel = "Toggle",
}) => {
    return (
        <button data-testid="button-b3567410" 
            id={id}
            type="button"
            role="switch"
            aria-checked={checked}
            aria-label={ariaLabel}
            disabled={disabled}
            onClick={() => !disabled && onChange(!checked)}
            className={
                [
                    "w-9.5 h-6 flex items-center rounded-full transition-colors duration-200 focus:outline-none min-w-[2.25rem]",
                    checked
                        ? "bg-primary"
                        : "bg-[#9799A3] dark:bg-[#515565]",
                    disabled ? "opacity-60 cursor-not-allowed" : "",
                    className
                ].join(" ")
            }
        >
            <span data-testid="span-b549b515" 
                className={[
                    "inline-block bg-backdrop-100 rounded-full shadow transition-transform duration-200 ",
                    checked ? "w-4 h-4 translate-x-[19px]" : "w-3 h-3 translate-x-1 mx-px"
                ].join(" ")}
            />
        </button>
    );
};

export default Toggle;
