// Chrome storage integration utilities
import {
  SETTING_ADS,
  SETTING_MALWARE,
  SETTING_SCAMS,
  SETTING_KILLSWITCH,
  SETTING_GTLD,
  SETTING_VERBOSE_LOGGING,
  SETTING_SEARCH_HIJACKING_NOTIFICATION,
  SETTING_TELEMETRY_CONSENT,
  MV3_PROTECTION_ADS,
  MV3_PROTECTION_MALWARE,
  MV3_PROTECTION_SCAMS,
  MSG_MV3_TOGGLE_INDIVIDUAL_PROTECTION,
  MSG_SETTINGS_GET,
  MSG_SETTINGS_SET,
  SETTING_MALICIOUS_NOTIFICATION,
  SETTING_MONTHLY_NOTIFICATION,
  SETTING_NEW_RELEASE_NOTIFICATION,
  SETTING_BREACH_NOTIFICATION,
  MV3_FEATURE_MONTHLY_NOTIFICATIONS,
  MV3_FEATURE_MALICIOUS_NOTIFICATIONS,
  MV3_FEATURE_NEW_RELEASE_NOTIFICATIONS,
  MV3_FEATURE_BREACH_NOTIFICATIONS,
  SETTING_BLOCK_COUNT,
  SETTING_SKIMMER_PROTECTION,
  MV3_FEATURE_SEARCH_HIJACKING_NOTIFICATIONS
} from "@/app/scripts/app-consts.js";

import { chrome } from '@/utils/polyfill'

// Utility to get settings from Chrome storage
export const settingsGetAsync = (
  settingIdConstant: string
): Promise<boolean> => {
  return new Promise((resolve, reject) => {
    chrome.runtime.sendMessage(
      { type: MSG_SETTINGS_GET, payload: settingIdConstant },
      function (response) {
        if (!response || response.error) {
          console.debug('SETTINGS GET ASYNC: ERROR CALLING settingsGet')
          reject(
            new Error(`Error calling settingsGet: ${
              response ? response.error : 'No response received'
            }`)
          )
        } else {
          resolve(response.success)
        }
      }
    )
  })
}

// Utility to set settings in Chrome storage
export const settingsSetAsync = (
  settingIdConstant: string,
  value: boolean
): Promise<boolean> => {
  return new Promise((resolve, reject) => {
    chrome.runtime.sendMessage(
      { type: MSG_SETTINGS_SET, payload: { [settingIdConstant]: value } },
      function (response) {
        if (!response || response.error) {
          console.debug('SETTINGS SET ASYNC: ERROR CALLING settingsSet')
          reject(
            new Error(`Error calling settingsSet: ${
              response ? response.error : 'No response received'
            }`)
          )
        } else {
          resolve(response.success)
        }
      }
    )
  })
}

// Utility to toggle individual protection via Chrome messaging
export const mv3ToggleIndividualProtection = (
  protection: string,
  enabled: boolean
): Promise<boolean> => {
  return new Promise((resolve, reject) => {
    chrome.runtime.sendMessage(
      {
        type: MSG_MV3_TOGGLE_INDIVIDUAL_PROTECTION,
        protection: protection,
        enable: enabled,
      },
      (response) => {
        if (!response || response.error) {
          console.error('Error calling MV3_TOGGLE_INDIVIDUAL_PROTECTION', {
            err: response.error,
            response,
          })
          reject(
            new Error(`Error calling MV3_TOGGLE_INDIVIDUAL_PROTECTION ${response.error}`)
          )
        } else {
          resolve(response.success)
        }
      }
    )
  })
}

