// Load protection settings from Chrome storage
export const loadProtectionSettings = async () => {
  try {
    const [
      enableProtection,
      enableProtectionAds,
      enableProtectionMalware,
      enableProtectionScams,
      enableProtectionGtld,
      enableBlockCountDisplay,
      enableSkimmerProtection,
      enableMaliciousNotification,
      enableMonthlyNotification,
      enableNewReleaseNotification,
      enableBreachNotification,
      enableSearchHijackingNotification,
      enableVerboseLogging,
    ] = await Promise.all([
      settingsGetAsync(SETTING_KILLSWITCH),
      settingsGetAsync(SETTING_ADS),
      settingsGetAsync(SETTING_MALWARE),
      settingsGetAsync(SETTING_SCAMS),
      settingsGetAsync(SETTING_GTLD),
      settingsGetAsync(SETTING_BLOCK_COUNT),
      settingsGetAsync(SETTING_SKIMMER_PROTECTION),
      settingsGetAsync(SETTING_MALICIOUS_NOTIFICATION),
      settingsGetAsync(SETTING_MONTHLY_NOTIFICATION),
      settingsGetAsync(SETTING_NEW_RELEASE_NOTIFICATION),
      settingsGetAsync(SETTING_BREACH_NOTIFICATION),
      settingsGetAsync(SETTING_SEARCH_HIJACKING_NOTIFICATION),
      settingsGetAsync(SETTING_VERBOSE_LOGGING),
    ])

    return {
      enableProtection,
      enableProtectionAds,
      enableProtectionMalware,
      enableProtectionScams,
      enableProtectionGtld,
      enableBlockCountDisplay,
      enableSkimmerProtection,
      enableMaliciousNotification,
      enableMonthlyNotification,
      enableNewReleaseNotification,
      enableBreachNotification,
      enableSearchHijackingNotification,
      enableVerboseLogging
    }
  } catch (error) {
    console.error('Error loading protection settings:', error)
    throw error
  }
}

// Save a specific protection setting to Chrome storage
export const saveProtectionSetting = async (
  key: keyof typeof CHROME_STORAGE_MAPPING,
  value: boolean
) => {
  const mapping = CHROME_STORAGE_MAPPING[key]
  if (!mapping) {
    throw new Error(`Unknown protection setting: ${key}`)
  }

  try {
    // First, set the setting in Chrome storage
    await settingsSetAsync(mapping.settingKey, value)

    // Then, if there's a protection key, trigger the MV3 protection change
    if (mapping.protectionKey) {
      await mv3ToggleIndividualProtection(mapping.protectionKey, value)
    } else {
      // For special cases like main protection or GTLD
      console.log(`Special handling needed for ${key}: ${value}`)
    }
  } catch (error) {
    console.error(`Error saving protection setting ${key}:`, error)
    throw error
  }
}
