import {
  EXCLUSION_ADS,
  EXCLUSION_MALWARE,
  EXCLUSION_SCAMS
} from "@/app/scripts/app-consts";
import type { ProtectionOption } from "../components/AllowList/AddAllowModal/types";

/**
 * Default protection options configuration
 */
export const createDefaultProtectionOptions = (): ProtectionOption[] => [
  { id: 'ads', key: EXCLUSION_ADS, label: 'Ads / Trackers', selected: false },
  { id: 'malware', key: EXCLUSION_MALWARE, label: 'Malware', selected: false },
  { id: 'scams', key: EXCLUSION_SCAMS, label: 'Scams', selected: false }
];

/**
 * Get selected protection keys for API submission
 */
export const getSelectedProtectionKeys = (protectionOptions: ProtectionOption[]): string[] => {
  return protectionOptions
    .filter(option => option.selected)
    .map(option => option.key);
};

/**
 * Toggle a protection option by ID
 */
export const toggleProtectionOption = (
  options: ProtectionOption[], 
  optionId: string
): ProtectionOption[] => {
  return options.map(option => 
    option.id === optionId 
      ? { ...option, selected: !option.selected }
      : option
  );
};

/**
 * Reset all protection options to unselected state
 */
export const resetProtectionOptions = (options: ProtectionOption[]): ProtectionOption[] => {
  return options.map(option => ({ ...option, selected: false }));
};
