import { useState, useCallback, useEffect } from 'react';
import { sendBackgroundMessage } from '@/utils/messaging/messaging';
import {
    MSG_DETECTION_HISTORY_GET_ALL,
    MSG_DETECTION_HISTORY_REMOVE_ALL,
    MSG_DETECTION_HISTORY_REMOVE_ITEM
} from '@/app/scripts/app-consts';
import { hasValidValues, transformDetectionItem, type RawDetectionItem } from './utils';
import type { DetectionRow, DeleteModalState } from './types';

/**
 * Custom hook for managing detection history data and operations
 */
export const useDetectionHistory = () => {
    const [detections, setDetections] = useState<DetectionRow[]>([]);
    const [loading, setLoading] = useState(false);
    const [deleteModal, setDeleteModal] = useState<DeleteModalState>({
        isOpen: false,
        detectionToDelete: null,
        isDeleting: false,
        isDeleteAll: false
    });

    const loadDetectionHistory = useCallback(async () => {
        try {
            setLoading(true);
            const response = await sendBackgroundMessage<void, RawDetectionItem[]>({
                type: MSG_DETECTION_HISTORY_GET_ALL
            });

            if (response.error) {
                console.error('Failed to load detection history:', response.error);
                return;
            }

            if (response.success) {
                const validItems = response.success.filter(hasValidValues);
                const transformedData = validItems.map(transformDetectionItem);

                setDetections(transformedData);
            }
        } catch (error) {
            console.error('Failed to load detection history:', error);
        } finally {
            setLoading(false);
        }
    }, []);

    // Load data on mount
    useEffect(() => {
        loadDetectionHistory();
    }, [loadDetectionHistory]);

    const openDeleteModal = (detection: DetectionRow) => {
        setDeleteModal({
            isOpen: true,
            detectionToDelete: detection,
            isDeleting: false,
            isDeleteAll: false
        });
    };

    const openDeleteAllModal = () => {
        setDeleteModal({
            isOpen: true,
            detectionToDelete: null,
            isDeleting: false,
            isDeleteAll: true
        });
    };

    const closeDeleteModal = () => {
        setDeleteModal({
            isOpen: false,
            detectionToDelete: null,
            isDeleting: false,
            isDeleteAll: false
        });
    };

    const confirmDelete = async () => {
        if (deleteModal.isDeleteAll) {
            // Delete all detections
            setDeleteModal(prev => ({ ...prev, isDeleting: true }));

            try {
                const response = await sendBackgroundMessage<void, void>({
                    type: MSG_DETECTION_HISTORY_REMOVE_ALL
                });

                if (!response.error) {
                    setDetections([]);
                    closeDeleteModal();
                }
            } catch (error) {
                console.error('Error clearing all detections:', error);
            } finally {
                setDeleteModal(prev => ({ ...prev, isDeleting: false }));
            }
        } else if (deleteModal.detectionToDelete) {
            // Delete single detection
            const detection = deleteModal.detectionToDelete;
            setDeleteModal(prev => ({ ...prev, isDeleting: true }));

            try {
                const payload = {
                    host: detection._raw?.hostData || detection.siteUrl,
                    rowId: detection._raw?.rowId || detection.id
                };

                const response = await sendBackgroundMessage<typeof payload, void>({
                    type: MSG_DETECTION_HISTORY_REMOVE_ITEM,
                    payload
                });

                if (!response.error) {
                    setDetections(prev => prev.filter(d => d.id !== detection.id));
                    closeDeleteModal();
                }
            } catch (error) {
                console.error('Error removing detection:', error);
            } finally {
                setDeleteModal(prev => ({ ...prev, isDeleting: false }));
            }
        }
    };

    return {
        detections,
        loading,
        deleteModal,
        openDeleteModal,
        openDeleteAllModal,
        closeDeleteModal,
        confirmDelete,
        refetch: loadDetectionHistory
    };
};
