import React from 'react';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import { t } from '$Popup/i18n';
import { UpdateState } from '../types';

export interface UpdateButtonProps {
  updateState: UpdateState;
  onUpdate: () => void;
}

/**
 * Database Update Button Component
 * Handles checking for database updates with visual feedback
 */
export const UpdateButton: React.FC<UpdateButtonProps> = ({ updateState, onUpdate }) => {
  const { isUpdating, isComplete, hasError } = updateState;

  const getButtonText = () => {
    if (isUpdating) return t('supportDbUpdating');
    if (isComplete) return t('supportDbComplete');
    return t('supportCheckForUpdates');
  };

  const getButtonIcon = () => {
    if (isUpdating) {
      return <BGSvgIcon iconName="settings" className="animate-spin w-4 h-4" />;
    }
    if (isComplete) {
      return <BGSvgIcon iconName="green-check" className="w-4 h-4 text-success" />;
    }
    return null;
  };

  return (
    <div data-testid="div-c0afb9bc"  className="update-section">
      <button data-testid="button-bf94c454" 
        onClick={onUpdate}
        disabled={isUpdating || isComplete}
        className={`
          inline-flex items-center px-6 py-2 rounded-full font-medium text-sm transition-colors
          ${isComplete 
            ? 'bg-success-100 text-success border border-success-200' 
            : isUpdating 
              ? 'bg-tragic-100 text-tragic-300 cursor-not-allowed'
              : 'bg-backdrop border border-primary text-primary hover:bg-tragic-100'
          }
        `}
      >
        {getButtonIcon() && (
          <span data-testid="span-957094f5"  className="mr-2">
            {getButtonIcon()}
          </span>
        )}
        {getButtonText()}
      </button>
      
      {hasError && (
        <div data-testid="div-fe286957"  className="mt-2">
          <p data-testid="p-a35b099a"  className='text-danger text-xs'>{t('supportCheckErrorLine1')}</p>
          <p data-testid="p-e2a02ee5"  className='text-danger text-xs'>{t('supportCheckErrorLine2')}</p>
        </div>
      )}
    </div>
  );
};
