/**
 * Context Detection Utility
 * 
 * Determines whether the extension is running in popup or tab context
 * using multiple detection methods for cross-browser compatibility.
 */

import { chrome } from "@/utils/polyfill";


export type ExtensionContext = 'popup' | 'tab';

/**
 * Simplified and reliable context detection for production use
 * @returns The detected context: 'popup' or 'tab'
 */
export const detectExtensionContext = (): ExtensionContext => {
  // Method 1: Primary detection using Chrome Extension API
  try {
    if (typeof chrome !== 'undefined' && chrome.extension && chrome.extension.getViews) {
      // Check if current window is a popup
      const popupViews = chrome.extension.getViews({ type: 'popup' });
      if (popupViews.includes(window)) {
        return 'popup';
      }
      
      // Check if current window is a tab
      const tabViews = chrome.extension.getViews({ type: 'tab' });
      if (tabViews.includes(window)) {
        return 'tab';
      }
      
      // If not found in either, check all views to see if we're an extension page
      const allViews = chrome.extension.getViews();
      if (allViews.includes(window)) {
        // We're an extension page but not specifically popup or tab
        // Fall back to dimension-based detection
        const isSmallWindow = window.outerWidth <= 700 && window.outerHeight <= 700;
        return isSmallWindow ? 'popup' : 'tab';
      }
    }
  } catch (e) {
    console.warn('Browser extension API not available, falling back to dimension detection');
  }
  
  // Method 2: Fallback - window dimensions for non-extension contexts or API failures
  const isSmallWindow = window.outerWidth <= 700 && window.outerHeight <= 700;
  return isSmallWindow ? 'popup' : 'tab';
};

/**
 * Checks if the current context is popup
 */
export const isPopupContext = (): boolean => {
  return detectExtensionContext() === 'popup';
};

/**
 * Checks if the current context is tab
 */
export const isTabContext = (): boolean => {
  return detectExtensionContext() === 'tab';
};
