import { useCallback, useState } from 'react'
import { chrome } from '@/utils/polyfill'
import { simpleStorageGet } from '@/utils/storage'
import { sendBackgroundMessage } from '@/utils/messaging/messaging'
import {
  MSG_ADD_ALLOW,
  MSG_ADD_ALLOW_TEMPORARY,
  THREAT_TYPES,
} from '@/app/scripts/app-consts'

const getExclusionConst = (type: string): string | null => {
  switch (type) {
    case 'ads':
    case 'ad':
      return 'EXCLUSION_ADS'
    case 'malware':
      return 'EXCLUSION_MALWARE'
    case 'scam':
    case 'phishing':
      return 'EXCLUSION_SCAMS'
    case 'user-block':
      return 'EXCLUSION_MALWARE'
    default:
      return null
  }
}

export function humanReadableSubType (subtype: string, type?: string) {
  console.log('BLOCK PAGE: humanReadableSubType', subtype, type);
    if (!subtype) {
        return type ?? chrome.i18n.getMessage('blockPageGenericThreat');
    }
    switch (subtype) {
        case THREAT_TYPES.MALWARE.FULL_URL_MALWARE:
            return "malware";
        case THREAT_TYPES.MALWARE.SUSPICIOUS_PAGE:
            return chrome.i18n.getMessage("humanReadableSubTypeSuspiciousPage");
        case THREAT_TYPES.MALWARE.SUSPICIOUS_TLD:
            return chrome.i18n.getMessage("humanReadableSubTypeSuspiciousTLD");
        case THREAT_TYPES.MALWARE.RISKY_PATTERN:
            return chrome.i18n.getMessage("humanReadableSubTypeRiskyPattern");
        case THREAT_TYPES.MALWARE.SUSPICIOUS_CONTENT:
            return chrome.i18n.getMessage("humanReadableSubTypeSuspiciousContent");
        case THREAT_TYPES.MALWARE.MALWARE_PATTERN:
            return chrome.i18n.getMessage("humanReadableSubTypeMalwarePattern");
        case THREAT_TYPES.MALWARE.ALERT_LOOP:
            return chrome.i18n.getMessage("humanReadableSubTypeAlertLoop");
        case THREAT_TYPES.MALWARE.AUTH_REQUIRED_LOOP:
            return chrome.i18n.getMessage("humanReadableSubTypeAuthRequiredLoop");
        case THREAT_TYPES.MALWARE.CREATE_URL_LOOP:
            return chrome.i18n.getMessage("humanReadableSubTypeCreateURLLoop");
        case THREAT_TYPES.MALWARE.EXTENSION_INSTALL:
            return chrome.i18n.getMessage("humanReadableSubTypeExtensionInstall");
        case THREAT_TYPES.MALWARE.FULL_SCREEN_LOOP:
            return chrome.i18n.getMessage("humanReadableSubTypeFullScreenLoop");
        case THREAT_TYPES.MALWARE.HISTORY_LOOP:
            return chrome.i18n.getMessage("humanReadableSubTypeHistoryLoop");
        case THREAT_TYPES.MALWARE.NOTIFICATION_LOOP:
            return chrome.i18n.getMessage("humanReadableSubTypeNotificationLoop");
        case THREAT_TYPES.MALWARE.PRINT_LOOP:
            return chrome.i18n.getMessage("humanReadableSubTypePrintLoop");
        case THREAT_TYPES.ADS.type:
        case THREAT_TYPES.ADS.ADSERVER:
            return chrome.i18n.getMessage("mv3TrackingAttempt");
        default:
            // Handle phishing prefixes
            if (subtype.startsWith(THREAT_TYPES.PHISHING.type)) {
                return "Phishing";
            }
            return subtype;
    }
};

export function useBlockPage() {
  const [continueAlways, setContinueAlways] = useState<boolean>(false)
  const [blockedUrl, setBlockedUrl] = useState<string>('')
  const [blockedHost, setBlockedHost] = useState<string>('')
  const [blockedType, setBlockedType] = useState<string>('')
  const [blockedSubtype, setBlockedSubtype] = useState<string>('')
  const [ruleId, setRuleId] = useState<string>('')
  const [activeTabId, setActiveTabId] = useState<number | null>(null)
  const [dbVersion, setDbVersion] = useState<string | null>(null)

  const initFromActiveTab = useCallback(async () => {    
    const tabs = await chrome.tabs.query({ active: true, currentWindow: true })
    if (!tabs.length) return
    const tab = tabs[0]
    const urlStr = tab.url || ''
    const urlObj = new URL(urlStr)
    const params = urlObj.searchParams
    let url = params.get('url') || ''
    let host = params.get('host') || ''
    let type = (params.get('type') || '').toLowerCase()
    let subtype = (params.get('subtype') || '')
    const rule = params.get('rule') || ''
    const dbv = await simpleStorageGet('lastDBused')

    // If we could not extract the type from the url, use the window params
    const windowSearchParams = new URLSearchParams(window.location.search);

    if (type === '') {      
      type = windowSearchParams.get('type')?.toLowerCase() ?? '';
      subtype = windowSearchParams.get('subtype')?.toLowerCase() ?? '';            
    }
    if (host === '') {
      host = windowSearchParams.get('host') ?? '';
    }
    if (url === '') {
      url = windowSearchParams.get('url') ?? '';
    }

    setActiveTabId(tab.id || null)
    setBlockedUrl(url.endsWith('/') ? url.slice(0, -1) : url)
    setBlockedHost(host)
    setBlockedType(type)
    setBlockedSubtype(subtype)
    setRuleId(rule.match(/\d+/)?.[0] || '')
    setDbVersion(dbv ?? null)
  }, [])

  const continueToSite = useCallback(async () => {

    const exclusion = getExclusionConst(blockedType)
    if (!exclusion) return
    const isSpecific = ['full-url-malware', 'malware-pattern'].includes(
      blockedSubtype
    )
    const toAllow = isSpecific ? blockedUrl : blockedHost

    if (continueAlways) {
      const resp = await sendBackgroundMessage({
        type: MSG_ADD_ALLOW,
        payload: { host: toAllow, allow: exclusion },
      })
      if (resp && !resp.error && activeTabId != null && blockedUrl) {
        await chrome.tabs.update(activeTabId, { url: blockedUrl })
      }
    } else {
      const resp = await sendBackgroundMessage({
        type: MSG_ADD_ALLOW_TEMPORARY,
        payload: { domain: blockedUrl || blockedHost, tabId: activeTabId },
      })
      if (resp && !resp.error && activeTabId != null && blockedUrl) {
        await chrome.tabs.update(activeTabId, { url: blockedUrl })
      }
    }
  }, [
    continueAlways,
    blockedSubtype,
    blockedType,
    blockedUrl,
    blockedHost,
    activeTabId,
  ])

  const goBack = useCallback(async () => {
    if (activeTabId == null) return
    // @ts-ignore - goBack may not exist in older type defs
    if (chrome.tabs.goBack) {
      // @ts-ignore
      await chrome.tabs.goBack(activeTabId)
    } else {
      await chrome.tabs.remove(activeTabId)
    }
  }, [activeTabId])

  return {
    continueAlways,
    setContinueAlways,
    initFromActiveTab,
    continueToSite,
    goBack,
    blockedUrl,
    blockedHost,
    blockedType,
    blockedSubtype,
    dbVersion,
    ruleId,
  }
}
