import { createColumnHelper, type ColumnDef } from "@tanstack/react-table";
import BGSvgIcon from "$Popup/components/core/BGSvgIcon";
import BGContextMenu, { MenuButton } from "$Popup/components/core/BGContextMenu";
import { t } from "$Popup/i18n";
import type { DetectionRow } from "./types";

const columnHelper = createColumnHelper<DetectionRow>();

export const createColumns = (
  detections: DetectionRow[],
  onDeleteAllClick?: () => void,
  onRemoveDetection?: (detection: DetectionRow) => void
): ColumnDef<DetectionRow, any>[] => [
  columnHelper.accessor("siteUrl", {
    header: t('SiteURL'),
    cell: (info) => (
      <span data-testid="span-e982ce75"  className="break-all text-sm">
        {info.getValue()}
      </span>
    ),
    meta: {
      headerClassName: "text-left",
      cellClassName: "py-3 px-4 text-left",
      align: "left",
    },
  }),
  
  columnHelper.accessor("type", {
    header: t('Type'),
    cell: (info) => (
      <span data-testid="span-125beb60" > {info.getValue()} </span>
    ),
    meta: {
      headerClassName: "text-left",
      cellClassName: "py-3 px-4 text-left",
      align: "left",
    },
  }),
  
  columnHelper.accessor("date", {
    header: t('Date'),
    cell: (info) => (
      <span data-testid="span-61b18d8a"  className="text-sm text-tragic-400">
        {info.getValue()}
      </span>
    ),
    meta: {
      headerClassName: "text-left",
      cellClassName: "py-3 px-4 text-left",
      align: "left",
    },
  }),
  
  columnHelper.display({
    id: "actions",
    header: () => (
      detections.length > 0 ? (
        <BGContextMenu
          trigger={
            <button data-testid="button-0ac37e79" 
              className="p-1 hover:bg-tragic-100 rounded transition-colors flex-shrink-0"
              aria-label="Actions menu"
            >
              <BGSvgIcon
                iconName="kebab-menu"
                size={16}
                className="opacity-60 hover:opacity-100 flex-shrink-0"
              />
            </button>
          }
        >
          <MenuButton
            onClick={onDeleteAllClick}
            className="text-danger hover:bg-primary-100"
          >
            {t('DeleteAll')}
          </MenuButton>
        </BGContextMenu>
      ) : null
    ),
    cell: (info) => (
      <BGContextMenu
        trigger={
          <button data-testid="button-bc2cdb50" 
            className="p-1 hover:bg-tragic-100 rounded transition-colors flex-shrink-0"
            aria-label={`Menu for ${info.row.original.siteUrl}`}
          >
            <BGSvgIcon
              iconName="kebab-menu"
              size={16}
              className="opacity-60 hover:opacity-100 flex-shrink-0"
            />
          </button>
        }
      >
        <MenuButton
          onClick={() => onRemoveDetection?.(info.row.original)}
          className="text-danger hover:bg-primary-100"
        >
          {t('Delete')}
        </MenuButton>
      </BGContextMenu>
    ),
    size: 48,
    minSize: 48,
    maxSize: 48,
    meta: {
      headerClassName: "w-12 text-right flex-shrink-0",
      cellClassName: "py-3 px-4 text-right flex-shrink-0",
      align: "right",
    },
  }),
];
