import { ScanStore } from "@/app/scripts/oap/scan-store";
import { useCallback, useEffect, useState } from "react";

export function useOAPPage() {
    const [isFirstTime, setIsFirstTime] = useState(false);

    const checkIfFirstTime = useCallback(async () => {
        const scanStore = new ScanStore();
        const scans = await scanStore.getScans();
        if (scans.length === 0) {
            setIsFirstTime(true);
        }
    }, []);

    return {
        checkIfFirstTime,
        isFirstTime,
    }
}