import {
  Carousel,
  CarouselApi,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
  CarouselStepper,
  useCarouselIndex,
} from '$Popup/components/core/BGCarousel'
import { OnboardingWelcome } from './Steps'
import DecorativeSVG from './DecorativeSVG'
import {
  BGButton,
  BGModal,
  BGSvgIcon,
  useModal,
} from '$Popup/components/core'
import { cn } from '$Popup/lib/utils'
import { useEffect, useState } from 'react'
import { useTranslation } from '$Popup/i18n/hooks'
import {
  useShowTutorial,
  useInitShowTutorial,
  useSetShowTutorialDone,
  useGeneralSettings,
  useToggleClipboardPermission,
} from '$Popup/store'
import { EXTERNAL_LINKS } from '$Popup/constants/links'
import Toggle from '$Popup/components/core/BGToggle'

const ONBOARDING_STEPS = [
  {
    titleKey: 'onboardingPinExtensionTitle',
    subTitleKey: 'onboardingPinExtensionSubtitle',
    descriptionKey: ['onboardingPinExtensionDesc1', 'onboardingPinExtensionDesc2'],
    illustration: 'pin-to-toolbar',
    stepperTitle: 'onboardingPinExtensionStepperTitle'
  },
  {
    titleKey: 'onboardingBrowsingProtectionTitle',
    subTitleKey: 'onboardingBrowsingProtectionSubtitle',
    descriptionKey: 'onboardingBrowsingProtectionDesc',
    illustration: 'protection-onboarding',
    stepperTitle: 'onboardingBrowsingProtectionStepperTitle'
  },
  {
    titleKey: 'onboardingStatsTitle',
    subTitleKey: 'onboardingStatsSubtitle',
    descriptionKey: 'onboardingStatsDesc',
    illustration: 'check-state-onboarding',
    stepperTitle: 'onboardingStatsStepperTitle'
  },
  {
    titleKey: 'onboardingAllowListTitle',
    subTitleKey: 'onboardingAllowListSubtitle',
    descriptionKey: 'onboardingAllowListDesc',
    illustration: 'allow-list-onboarding',
    stepperTitle: 'onboardingAllowListStepperTitle'
  }
]
const OnboardingModal = () => {
  const [api, setApi] = useState<CarouselApi | undefined>(undefined)
  const [selectedIndex, setSelectedIndex] = useState(0)
  const { t } = useTranslation()
  const onBoardingModal = useModal()
  const showTutorial = useShowTutorial()
  const initShowTutorial = useInitShowTutorial()
  const setTutorialDone = useSetShowTutorialDone()
  const { enableClipboardReadPermission } = useGeneralSettings()
  const toggleClipboardPermission = useToggleClipboardPermission()

  useEffect(() => {
    initShowTutorial()
  }, [initShowTutorial])

  useEffect(() => {
    if (showTutorial) {
      onBoardingModal.openModal()
    } else {
      onBoardingModal.closeModal()
    }
  }, [showTutorial])

  useEffect(() => {
    if (!api) return
    const update = () => setSelectedIndex((api as any).selectedScrollSnap())
    update()
    api.on('select', update)
    api.on('reInit', update)
    return () => {
      api.off('select', update)
      api.off('reInit', update)
    }
  }, [api])

  return (
    <BGModal
      showCloseButton={false}
      className={cn('min-w-[600px]')}
      isOpen={onBoardingModal.isOpen}
      onClose={setTutorialDone}
    >

      {selectedIndex === 0 ? <DecorativeSVG /> : null}
      <Carousel
        setApi={setApi}
        opts={{ watchDrag: false }}
      >
        {selectedIndex > 1 && <CarouselStepper steps={ONBOARDING_STEPS} />}
        <CarouselContent 
          onComplete={setTutorialDone}
          completeButtonText={t('doneText')}
        >
          <CarouselItem className="relative">
            <OnboardingWelcome />
          </CarouselItem>
          <CarouselItem>
            <div data-testid="div-19785714"  className="flex flex-col items-center justify-between h-full">
              <h5 data-testid="h5-49fdca8a"  className="text-tragic-400">{t('clipboardContentProtectionTitle')}</h5>
              <p data-testid="p-9de68a77"  className="text-md font-normal text-tragic-400"> {t('clipboardContentProtectionDesc')} </p>
              <div data-testid="div-9ca44b43"  className="bg-liteblue rounded-xl flex justify-center items-center w-full py-10">
                <BGSvgIcon iconName="clipboard-protection" size={150} />
              </div>

              <div data-testid="div-0b5c847c"  className="min-h-32">
                <div data-testid="div-bdb49fd4"  className='flex justify-between'>
                  <h6 data-testid="h6-c9a0f961"  className="font-medium text-base mb-1 text-tragic-400"> {t('clipboardReadPermissionTitle')}</h6>
                  <Toggle checked={enableClipboardReadPermission} onChange={toggleClipboardPermission} />
                </div>
                <p data-testid="p-4de4d846"  className="text-sm text-tragic-400 pr-10">
                  {t('clipboardReadPermissionDesc')}
                </p>
              </div>
            </div>
          </CarouselItem>
          {ONBOARDING_STEPS.map(({ titleKey, subTitleKey, descriptionKey, illustration }) => (
            <CarouselItem key={titleKey}>
              <div data-testid="div-0a7d633f"  className="flex flex-col items-center justify-between h-[calc(100%-1rem)]">
                <div data-testid="div-fdd0f488"  className="flex flex-col items-center gap-5 mt-2 w-full">
                  <h4 data-testid="h4-098629b3" >{t(titleKey)}</h4>
                  <p data-testid="p-f9c70459"  className="text-md font-normal text-tragic-400">{t(subTitleKey)}</p>
                </div>
                <div data-testid="div-4cfb06a9"  className="flex justify-between">
                  <div data-testid="div-9dc0c371"  className="basis-1/2 pr-8">
                    {Array.isArray(descriptionKey) ? (
                      // use p for multiple descriptions like, 1. something 2. something
                      descriptionKey.map((desc, index) => (
                        <p data-testid={`p-ccd56516-${index}`} key={index} className="text-md font-normal text-tragic-400 leading-6 mb-2">
                          {index + 1}. {t(desc)}
                        </p>
                      ))
                    ) : (
                      <p data-testid="p-a4701767"  className="text-md font-normal text-tragic-400 leading-6">{t(descriptionKey)}</p>
                    )}
                  </div>
                  <BGSvgIcon className="basis-1/2" iconName={illustration} width={320} />
                </div>
              </div>
            </CarouselItem>
          ))}
        </CarouselContent>
      </Carousel>
    </BGModal>
  )
}

export default OnboardingModal
