import React from 'react';
import { MenuButton } from '$Popup/components/core/BGContextMenu';
import BGSvgIcon from '$Popup/components/core/BGSvgIcon';
import { TopBarMenuProps } from './types';
import { BUTTON_CLASSES, shareSubmenuItems } from './config';
import { useTopBarMenuActions } from './hooks';
import ShareSubmenu from './ShareSubmenu';
import { t } from '$Popup/i18n';

/**
 * TopBarMenu - Account/Profile dropdown menu for the TopBar
 * 
 * Contains user account actions and support options.
 * Organized with proper separation of concerns:
 * - types.ts: TypeScript interfaces
 * - config.ts: Menu configuration and constants
 * - hooks.ts: Custom hooks and business logic
 * - ShareSubmenu.tsx: Submenu component
 * - index.tsx: Main component (this file)
 */
const TopBarMenu: React.FC<TopBarMenuProps> = ({ className = '' }) => {
    const {
        // State
        showShareSubmenu,
        submenuPosition,
        shareButtonRef,
        submenuRef,
        
        // Actions
        handleViewTutorial,
        handleSupportOpen,
        handleShareExtensionClick,
        handleExternalLink,
        handleCopyLink
    } = useTopBarMenuActions();

    return (
        <div data-testid="div-ee9f14b9"  className={className}>
            {/* Support */}
            <MenuButton
                id="top-bar-menu-support-button"
                onClick={handleSupportOpen}
                className={BUTTON_CLASSES}
            >
                <span data-testid="span-811b07cd"  className="text-tragic">{t('supportMenuItem')}</span>
            </MenuButton>

            {/* View Tutorial */}
            <MenuButton
                id="top-bar-menu-view-tutorial-button"
                onClick={handleViewTutorial}
                className={BUTTON_CLASSES}
            >
                <span data-testid="span-9a1a7f65"  className="text-tragic">{t('viewTutorialMenuItem')}</span>
            </MenuButton>

            {/* Share Extension with Submenu */}
            <button data-testid="button-aeebd353" 
                ref={shareButtonRef}
                type="button"
                className={BUTTON_CLASSES}
                onClick={(e) => {
                    e.stopPropagation();
                    handleShareExtensionClick();
                }}
            >
                <div data-testid="div-a6b26476"  className="flex items-center justify-between w-full">
                    <span data-testid="span-3912922e"  className="text-tragic">{t('shareExtensionMenuItem')}</span>
                    <span data-testid="span-ed2097bd"  className={`text-tragic-400 transition-transform duration-200 ${showShareSubmenu ? 'rotate-90' : ''}`}>
                        <BGSvgIcon iconName="right-arrow" size={18} />
                    </span>
                </div>
            </button>

            {/* Share Submenu */}
            <ShareSubmenu
                isOpen={showShareSubmenu}
                position={submenuPosition}
                submenuRef={submenuRef}
                submenuItems={shareSubmenuItems}
                onExternalLink={handleExternalLink}
                onCopyLink={handleCopyLink}
            />
        </div>
    );
};

export default TopBarMenu;
