import * as React from "react";
import { BGModal } from "$Popup/components/core/BGModal/BGModal";
import { t } from "$Popup/i18n";
import { DELETE_ALL_MARKER } from "../ContentControlTable/hooks";

interface DeleteConfirmModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  loading?: boolean;
  websiteDomain?: string;
}

const DeleteConfirmModal: React.FC<DeleteConfirmModalProps> = ({ 
  isOpen, 
  onClose, 
  onConfirm, 
  loading = false,
  websiteDomain 
}) => {
  const isDeleteAll = websiteDomain === DELETE_ALL_MARKER;
  
  return (
    <BGModal
      isOpen={isOpen}
      onClose={loading ? () => {} : onClose}
      title={isDeleteAll ? t("RemoveAllContentControlSiteConfirmation") : t("RemoveContentControlSiteConfirmation")}
      className="max-w-md"
    >
      <div data-testid="div-fd420ca9"  className="space-y-6">
        {/* Description */}
        <div data-testid="div-abb1d7a6" >
          <p data-testid="p-d8b6f409"  className="text-tragic text-sm leading-relaxed">
            {isDeleteAll 
              ? t("RemoveAllContentControlWarning")
              : t("RemoveContentControlWarning")
            }
          </p>
        </div>

        {/* Action Buttons */}
        <div data-testid="div-9c7c503d"  className="flex justify-end gap-3 pt-2">
          <button data-testid="button-d8154a78" 
            onClick={onClose}
            disabled={loading}
            className="px-6 py-2 text-sm font-medium text-primary border border-primary rounded-4xl hover:bg-tragic-100 transition-colors disabled:opacity-50"
          >
            {t("Cancel")}
          </button>
          <button data-testid="button-5068b79c" 
            onClick={onConfirm}
            disabled={loading}
            className={`px-6 py-2 text-sm font-medium rounded-4xl transition-colors disabled:opacity-50 disabled:cursor-not-allowed ${
              loading
                ? 'bg-tragic-300 text-backdrop'
                : 'bg-primary text-backdrop hover:bg-primary-hover'
            }`}
          >
            {loading ? (
              <span data-testid="span-8ace90ea"  className="flex items-center">
                <span data-testid="span-2e60a8bc"  className="animate-spin mr-2">⏳</span>
                {isDeleteAll ? t('RemovingAll') : t('Removing')}
              </span>
            ) : (
              isDeleteAll ? t('RemoveAllBtn') : t('RemoveBtn')
            )}
          </button>
        </div>
      </div>
    </BGModal>
  );
};

export default DeleteConfirmModal;
