import type { ChartOptions } from 'chart.js';

/**
 * Get CSS custom property value
 */
export const getThemeColor = (property: string): string => {
  if (typeof window !== 'undefined') {
    return getComputedStyle(document.documentElement).getPropertyValue(property).trim();
  }
  return '#0D3ECC'; // fallback primary color
};

/**
 * Format number with K/M suffixes
 */
export const formatNumber = (num: number): string => {
  if (num >= 1000000) return `${(num / 1000000).toFixed(1)} M`;
  if (num >= 1000) return `${(num / 1000).toFixed(1)} K`;
  return num.toString();
};

/**
 * Generate Chart.js configuration
 */
export const getChartOptions = (): ChartOptions<'line'> => ({
  responsive: true,
  maintainAspectRatio: false,
  layout: {
    padding: {
      left: 35,
    }
  },
  plugins: {
    legend: { display: false },
    tooltip: {
      backgroundColor: getThemeColor('--color-backdrop'),
      borderColor: getThemeColor('--color-tragic-200'),
      borderWidth: 1,
      titleColor: getThemeColor('--color-tragic'),
      bodyColor: getThemeColor('--color-tragic'),
      cornerRadius: 8
    }
  },
  scales: {
    y: {
      beginAtZero: true,
      ticks: {
        precision: 0,
        color: getThemeColor('--color-tragic-400') + 'A6',
        padding: -11,
        maxTicksLimit: 6,
        mirror: true,
        z: 1,
        callback: function(value: any) {
          return formatNumber(Number(value));
        }
      },
      grid: {
        color: getThemeColor('--color-tragic-200'),
        drawOnChartArea: true,
        drawTicks: false
      },
      border: { display: false }
    },
    x: {
      ticks: {
        color: getThemeColor('--color-tragic-400') + 'A6',
      },
      grid: { display: false },
      border: { display: false }
    }
  },
  elements: {
    line: { tension: 0.1 },
    point: { radius: 0 }
  }
});

/**
 * Generate chart data configuration
 */
export const generateChartData = (
  chartData: Array<{ date: string; [key: string]: any }>,
  selectedCategory: string,
  selectedLabel: string
) => {
  const selectedData = chartData.map(point => point[selectedCategory]);

  return {
    labels: chartData.map(point => point.date),
    datasets: [{
      label: selectedLabel || 'Blocked',
      data: selectedData,
      borderColor: getThemeColor('--color-primary'),
      backgroundColor: 'transparent',
      borderWidth: 1.5,
      pointRadius: 5,
      pointHoverRadius: 7,
      pointBackgroundColor: getThemeColor('--color-backdrop'),
      pointBorderColor: getThemeColor('--color-primary'),
      pointBorderWidth: 1.5
    }]
  };
};
