export type StatusVariant = "warning" | "success" | "danger" | "info";

export interface ProtectionCardData {
  header: string;
  id: string;
  mainIconName: string;
  statusText: string;
  statusVariant: StatusVariant;
  description: string;
  btnText: string;
  btnLink: string;
}

export interface ProtectionStatus {
  isLoading: boolean;
  error: string | null;
}

export interface NativeHostStatus extends ProtectionStatus {
  isConnected: boolean;
  refetch: () => Promise<void>;
}

export interface LicenseState extends ProtectionStatus {
  licenseState: number | null;
  refetch: () => Promise<void>;
}

// License state constants from app-consts.js
export const LICENSE_STATES = {
  Free: 1,
  Trial: 2,
  TrialExpired: 3,
  Licensed: 4,
  LicenseExpired: 5,
  LicenseGrace: 6
} as const;

export const PREMIUM_LICENSE_STATES = [2, 4, 6] as const;
export type PremiumLicenseStateValue = typeof PREMIUM_LICENSE_STATES[number];
