import { useState, useEffect, useCallback } from 'react'
import {
  settingsGetAsync,
  settingsSetAsync,
} from '$Popup/store/chromeStorage/generalSettings'
import { BROWSER_NAME, SETTING_TELEMETRY_CONSENT } from '@/app/scripts/app-consts.js'
import { TARGET_BROWSER } from '@/app/scripts/browser-const'

interface UseTelemetryOptInReturn {
  showTelemetryOptIn: boolean
  isOptedIn: boolean
  isLoading: boolean
  error: string | null
  handleChange: (value: boolean) => void
  toggleOptIn: (newValue: boolean) => Promise<void>
}

const useTelemetryOptIn = (): UseTelemetryOptInReturn => {
  // @ts-ignore
  const [showTelemetryOptIn] = useState<boolean>(TARGET_BROWSER !== BROWSER_NAME.Firefox)
  const [isOptedIn, setIsOptedIn] = useState<boolean>(false)
  const [isLoading, setIsLoading] = useState<boolean>(true)
  const [error, setError] = useState<string | null>(null)

  // Initialize the opt-in state from chrome storage
  useEffect(() => {
    const initializeTelemetryState = async () => {
      try {
        setIsLoading(true)

        // Get current telemetry consent setting using existing utility
        const response = await settingsGetAsync(SETTING_TELEMETRY_CONSENT)

        // Set initial state (defaults to true if not false)
        setIsOptedIn(response !== false)
        setError(null)
      } catch (err) {
        console.error('Failed to load telemetry consent setting:', err)
        setError(err as string)
        setIsOptedIn(false) // Default to opted out on error
      } finally {
        setIsLoading(false)
      }
    }

    initializeTelemetryState()
  }, [])

  // Handle toggling the opt-in state
  const toggleOptIn = useCallback(async (newValue: boolean) => {
    try {
      setIsLoading(true)

      // Update the setting in chrome storage using existing utility
      await settingsSetAsync(SETTING_TELEMETRY_CONSENT, newValue)

      // Update local state
      setIsOptedIn(newValue)
      setError(null)

      console.debug('Telemetry consent updated:', newValue)
    } catch (err) {
      console.error('Failed to update telemetry consent:', err)
      setError(err as string)
      // Revert the checkbox state on error
      setIsOptedIn(!newValue)
    } finally {
      setIsLoading(false)
    }
  }, [])

  // Handle checkbox change event
  const handleChange = useCallback(
    (newValue) => {
      toggleOptIn(newValue)
    },
    [toggleOptIn]
  )

  return {
    showTelemetryOptIn,
    isOptedIn,
    isLoading,
    error,
    handleChange,
    toggleOptIn,
  }
}

export default useTelemetryOptIn
