import { useState, useCallback } from 'react';
import { chrome } from '@/utils/polyfill';
import {
  MSG_DOWNLOAD_LOGS,
  MSG_FORCE_DATABASE_UPDATE,
  MSG_RESET,
  PORT_FORCE_DATABASE_UPDATE
} from '@/app/scripts/app-consts.js';
import { downloadLogsToFile } from '@/utils/utils.js';
import { UpdateState, SupportActions } from '../types';
import { sendBackgroundMessage } from '@/utils/messaging/messaging';
import { DownloadLogsRequest, DownloadLogsResponse } from '@/utils/messaging/types';


/**
 * Hook for managing support actions
 * Handles downloads, updates, and factory reset functionality
 */
export const useSupportActions = (): SupportActions => {
  const [updateState, setUpdateState] = useState<UpdateState>({
    isUpdating: false,
    isComplete: false,
    hasError: false
  });
  const [resetModalOpen, setResetModalOpen] = useState<boolean>(false);

  const downloadLogs = useCallback(async () => {
    const response = await sendBackgroundMessage<DownloadLogsRequest, DownloadLogsResponse>({type: MSG_DOWNLOAD_LOGS})
    if (response.success) {
      downloadLogsToFile((response as DownloadLogsResponse).data);
    }
  }, []);

  const checkForUpdates = useCallback(() => {
    setUpdateState({
      isUpdating: true,
      isComplete: false,
      hasError: false
    });

    const port = chrome.runtime.connect({ name: PORT_FORCE_DATABASE_UPDATE });
    port.postMessage({ message: MSG_FORCE_DATABASE_UPDATE });

    port.onMessage.addListener((message) => {
      if (message.message === 'UPDATE_STARTED') {
        setUpdateState(prev => ({ ...prev, isUpdating: true }));
      } else if (message.message === 'UPDATE_COMPLETED') {
        setUpdateState({
          isUpdating: false,
          isComplete: true,
          hasError: false
        });
        port.disconnect();
      } else if (message.message === 'UPDATE_FAILED') {
        setUpdateState({
          isUpdating: false,
          isComplete: false,
          hasError: true
        });
        port.disconnect();
      }
    });
  }, []);

  const factoryReset = useCallback(() => {
    chrome.runtime.sendMessage({ type: MSG_RESET }, () => {
      setResetModalOpen(false);
    });
  }, []);

  const resetState = useCallback(() => {
    setUpdateState({
      isUpdating: false,
      isComplete: false,
      hasError: false
    });
    setResetModalOpen(false);
  }, []);

  return {
    updateState,
    resetModalOpen,
    downloadLogs,
    checkForUpdates,
    factoryReset,
    setResetModalOpen,
    resetState
  };
};
