import { StateCreator } from 'zustand';
import { TabSlice, TabsData, TabData } from '$Popup/store/types';
import {
    getCurrentTabId,
    getTabDataFromBackground,
    loadTabsDataFromStorage,
    saveTabsDataToStorage,
    loadCurrentTabId,
    saveCurrentTabId,
    saveTabData,
    removeTabData,
    clearAllTabData,
} from '$Popup/store/chromeStorage/tabStorage';

export const createTabSlice: StateCreator<TabSlice> = (set, get) => ({
    // Initial state
    tabsData: {},
    currentTabId: null,
    isLoading: false,

    // Actions
    setTabData: (tabId, tabData) => {
        set((state) => ({
            ...state,
            tabsData: {
                ...state.tabsData,
                [tabId.toString()]: tabData,
            },
        }));

        // Save to Chrome storage
        saveTabData(tabId, tabData).catch((error) => {
            console.error(`Failed to save tab data for tab ${tabId}:`, error);
        });
    },

    updateTabBlocked: (tabId, blocked) => {
        const currentTabData = get().tabsData[tabId.toString()];
        if (!currentTabData) {
            console.warn(`Cannot update blocked data for non-existent tab ${tabId}`);
            return;
        }

        const updatedTabData: TabData = {
            ...currentTabData,
            blocked,
            // Also update blockedHistory with the same data
            blockedHistory: blocked,
        };

        get().setTabData(tabId, updatedTabData);
    },

    setCurrentTabId: (tabId) => {
        set((state) => ({
            ...state,
            currentTabId: tabId,
        }));

        // Save to Chrome storage
        saveCurrentTabId(tabId).catch((error) => {
            console.error('Failed to save current tab ID:', error);
        });
    },

    getCurrentTabData: () => {
        const { currentTabId, tabsData } = get();
        if (!currentTabId) return null;
        return tabsData[currentTabId.toString()] || null;
    },

    loadTabsData: async () => {
        try {
            set((state) => ({ ...state, isLoading: true }));

            // Load tabs data from storage
            const tabsData = await loadTabsDataFromStorage();
            
            // Load current tab ID from storage
            const currentTabId = await loadCurrentTabId();
            
            // If no current tab ID in storage, get the actual current tab
            let actualCurrentTabId = currentTabId;
            if (!actualCurrentTabId) {
                actualCurrentTabId = await getCurrentTabId();
            }

            // If we have a current tab but no data for it, fetch from background
            if (actualCurrentTabId && !tabsData[actualCurrentTabId.toString()]) {
                try {
                    const currentTabData = await getTabDataFromBackground(actualCurrentTabId);
                    if (currentTabData) {
                        tabsData[actualCurrentTabId.toString()] = currentTabData;
                        // Save the new data back to storage
                        await saveTabData(actualCurrentTabId, currentTabData);
                    }
                } catch (error) {
                    console.error('Failed to fetch current tab data from background:', error);
                }
            }

            set((state) => ({
                ...state,
                tabsData,
                currentTabId: actualCurrentTabId,
            }));

            // Save current tab ID if it was updated
            if (actualCurrentTabId !== currentTabId) {
                await saveCurrentTabId(actualCurrentTabId);
            }

        } catch (error) {
            console.error('Failed to load tabs data:', error);
            throw error;
        } finally {
            set((state) => ({ ...state, isLoading: false }));
        }
    },

    clearTabData: (tabId) => {
        if (tabId) {
            // Clear specific tab
            set((state) => {
                const newTabsData = { ...state.tabsData };
                delete newTabsData[tabId.toString()];
                return {
                    ...state,
                    tabsData: newTabsData,
                    currentTabId: state.currentTabId === tabId ? null : state.currentTabId,
                };
            });

            // Remove from storage
            removeTabData(tabId).catch((error) => {
                console.error(`Failed to remove tab data for tab ${tabId}:`, error);
            });
        } else {
            // Clear all tabs
            set((state) => ({
                ...state,
                tabsData: {},
                currentTabId: null,
            }));

            // Clear from storage
            clearAllTabData().catch((error) => {
                console.error('Failed to clear all tab data:', error);
            });
        }
    },
});
