// Protection state constants
export const FULLY_PROTECTED = "FULLY_PROTECTED";
export const PARTIALLY_PROTECTED = "PARTIALLY_PROTECTED";
export const NOT_PROTECTED = "NOT_PROTECTED";
export const EMPTY_PAGE = "EMPTY_PAGE";

/**
 * Determines the overall protection state based on protection toggle states
 * @param protectionSettings - Object containing protection toggle states (ads, malware, scams)
 * @returns Protection state constant string
 */
export const protectionState = (protectionSettings: { ads: boolean; malware: boolean; scams: boolean }): string => {
    const { ads, malware, scams } = protectionSettings;
    const protectionToggles = [ads, malware, scams];

    // Count how many protections are enabled
    const enabledCount = protectionToggles.filter(Boolean).length;
    const totalCount = protectionToggles.length;

    if (enabledCount === totalCount) {
        return FULLY_PROTECTED;
    } else if (enabledCount === 0) {
        return NOT_PROTECTED;
    } else {
        return PARTIALLY_PROTECTED;
    }
};
