import { StateCreator } from 'zustand'
import {
  SiteProtectionSlice,
  DEFAULT_SITE_PROTECTION_SETTINGS,
} from '$Popup/store/types'
import {
  saveSiteProtections,
  clearAllSiteProtections as clearAllSiteProtectionsStorage,
} from '@/app/popup/src/store/chromeStorage/siteProtection'
import { sendBackgroundMessage } from '@/utils/messaging/messaging'
import {
  EXCLUSION_ADS,
  EXCLUSION_MALWARE,
  EXCLUSION_SCAMS,
  MSG_WEBSITE_CHECKBOX_GET,
  MSG_ADD_ALLOW,
  MSG_REM_ALLOW_SINGLE,
} from '@/app/scripts/app-consts'
import {
  getShowTutorial,
  setShowTutorial,
} from '$Popup/store/chromeStorage/dashboard'

// Mapping from protection type to exclusion constant
const PROTECTION_TYPE_TO_EXCLUSION = {
  ads: EXCLUSION_ADS,
  malware: EXCLUSION_MALWARE,
  scams: EXCLUSION_SCAMS,
} as const

export const createSiteProtectionSlice: StateCreator<SiteProtectionSlice> = (
  set,
  get
) => ({
  // Initial state
  siteProtections: {},
  isLoading: false,
  showTutorial: false,

  // Actions
  initShowTutorial: async () => {
    try {
      const stored = await getShowTutorial()
      if (stored === undefined) {
        set((state) => ({ ...state, showTutorial: true }))
        await setShowTutorial(false)
      } else {
        set((state) => ({ ...state, showTutorial: false }))
      }
    } catch (error) {
      console.error('siteProtectionSlice: Failed to init showTutorial:', error)
      set((state) => ({ ...state, showTutorial: false }))
    }
  },

  setShowTutorialDone: async () => {
    try {
      set((state) => ({ ...state, showTutorial: false }))
      await setShowTutorial(false)
    } catch (error) {
      console.error('siteProtectionSlice: Failed to mark tutorial done:', error)
    }
  },

  setSiteProtections: (protections) => {
    set((state) => ({
      ...state,
      siteProtections: protections,
    }))

    // Save to Chrome storage
    saveSiteProtections(protections).catch((error) => {
      console.error(
        'siteProtectionSlice: Failed to save site protections:',
        error
      )
    })
  },

  toggleSiteProtection: async (hostname, protectionType) => {
    try {
      set((state) => ({ ...state, isLoading: true }))

      // Get current protection state
      const currentState =
        get().siteProtections[hostname]?.[protectionType] ??
        DEFAULT_SITE_PROTECTION_SETTINGS[protectionType]
      const newState = !currentState

      console.log(
        `siteProtectionSlice: Toggling ${protectionType} for ${hostname}: ${currentState} -> ${newState}`
      )

      // Get the exclusion constant for this protection type
      const exclusionConst = PROTECTION_TYPE_TO_EXCLUSION[protectionType]
      if (!exclusionConst) {
        throw new Error(`Unknown protection type: ${protectionType}`)
      }

      const messageType = newState ? MSG_REM_ALLOW_SINGLE : MSG_ADD_ALLOW
      const payload = newState
        ? {
            host: hostname,
            exclusion: exclusionConst,
            override: true,
            originalHost: hostname,
          }
        : { host: hostname, allow: exclusionConst, originalHost: hostname }

      console.log(
        `siteProtectionSlice: Sending message: ${messageType}`,
        payload
      )

      // Call background script based on new state

      const response = await sendBackgroundMessage({
        type: messageType,
        payload: payload,
      })

      console.log(
        `siteProtectionSlice: Background response for ${protectionType}:`,
        response
      )

      if (response.error) {
        console.error(
          `siteProtectionSlice: Failed to toggle protection for ${protectionType}:`,
          response.error
        )
        throw new Error(response.error)
      }

      // Update local state only if background call succeeded
      set((state) => {
        const currentSiteProtections =
          state.siteProtections[hostname] || DEFAULT_SITE_PROTECTION_SETTINGS
        const newSiteProtections = {
          ...currentSiteProtections,
          [protectionType]: newState,
        }

        console.log(`siteProtectionSlice: Updating state for ${hostname}:`, {
          before: currentSiteProtections,
          after: newSiteProtections,
        })

        return {
          ...state,
          siteProtections: {
            ...state.siteProtections,
            [hostname]: newSiteProtections,
          },
        }
      })

      console.log(
        `siteProtectionSlice: Toggle completed for ${protectionType}: ${currentState} -> ${newState}`
      )

      return newState
    } catch (error) {
      console.error(
        `siteProtectionSlice: Failed to toggle site protection ${protectionType} for ${hostname}:`,
        error
      )
      throw error
    } finally {
      set((state) => ({ ...state, isLoading: false }))
    }
  },

  isSiteProtected: (hostname, protectionType) => {
    const { siteProtections } = get()
    return (
      siteProtections[hostname]?.[protectionType] ??
      DEFAULT_SITE_PROTECTION_SETTINGS[protectionType]
    )
  },

  getSiteProtections: (hostname) => {
    const { siteProtections } = get()
    return siteProtections[hostname] || DEFAULT_SITE_PROTECTION_SETTINGS
  },

  loadSiteProtections: async (hostname: string) => {
    try {
      set((state) => ({ ...state, isLoading: true }))

      if (!hostname) {
        console.warn(
          'siteProtectionSlice: No hostname provided to loadSiteProtections'
        )
        return
      }

      console.log(
        `siteProtectionSlice: Loading site protections for: ${hostname}`
      )

      // Call background script for each exclusion type
      const exclusionTypes = [
        { const: EXCLUSION_ADS, key: 'ads' as const },
        { const: EXCLUSION_MALWARE, key: 'malware' as const },
        { const: EXCLUSION_SCAMS, key: 'scams' as const },
      ]

      const siteProtectionSettings = { ...DEFAULT_SITE_PROTECTION_SETTINGS }

      // Make parallel calls to get protection status for each type
      const protectionPromises = exclusionTypes.map(
        async ({ const: exclusionConst, key }) => {
          try {
            console.log(
              `siteProtectionSlice: Checking ${key} protection status for ${hostname}`
            )
            const response = await sendBackgroundMessage({
              type: MSG_WEBSITE_CHECKBOX_GET,
              payload: { const: exclusionConst, url: hostname },
            })

            console.log(`siteProtectionSlice: Response for ${key}:`, response)

            if (response.error) {
              console.error(
                `siteProtectionSlice: Error getting protection status for ${key}:`,
                response.error
              )
              return { key, value: DEFAULT_SITE_PROTECTION_SETTINGS[key] }
            }

            // The response.success indicates if protection is enabled (checkbox checked)
            const protectionEnabled = response.success || false
            console.log(
              `siteProtectionSlice: ${key} protection for ${hostname}: ${protectionEnabled}`
            )
            return { key, value: protectionEnabled }
          } catch (error) {
            console.error(
              `siteProtectionSlice: Failed to get protection status for ${key}:`,
              error
            )
            return { key, value: DEFAULT_SITE_PROTECTION_SETTINGS[key] }
          }
        }
      )

      const results = await Promise.all(protectionPromises)

      // Update the site protection settings with the results
      results.forEach(({ key, value }) => {
        siteProtectionSettings[key] = value
      })

      console.log(
        `siteProtectionSlice: Final protection settings for ${hostname}:`,
        siteProtectionSettings
      )

      // Update the state with the hostname's protection settings
      set((state) => ({
        ...state,
        siteProtections: {
          ...state.siteProtections,
          [hostname]: siteProtectionSettings,
        },
      }))
    } catch (error) {
      console.error(
        'siteProtectionSlice: Failed to load site protections:',
        error
      )
      throw error
    } finally {
      set((state) => ({ ...state, isLoading: false }))
    }
  },

  clearAllSiteProtections: async () => {
    try {
      set((state) => ({ ...state, isLoading: true }))

      await clearAllSiteProtectionsStorage()

      set((state) => ({
        ...state,
        siteProtections: {},
      }))
    } catch (error) {
      console.error(
        'siteProtectionSlice: Failed to clear all site protections:',
        error
      )
      throw error
    } finally {
      set((state) => ({ ...state, isLoading: false }))
    }
  },
})
