import { useState, useCallback } from "react";
import { sendBackgroundMessage } from "@/utils/messaging/messaging";
import { MSG_ADD_ALLOW } from "@/app/scripts/app-consts";
import { validateUrl, processAllowListInput } from "$Popup/utils/urlValidation";
import { 
  createDefaultProtectionOptions, 
  getSelectedProtectionKeys, 
  toggleProtectionOption, 
  resetProtectionOptions 
} from "$Popup/utils/protectionOptions";
import type { FormState, ProtectionOption } from "./types";

/**
 * Custom hook for managing AddAllowModal form state and actions
 */
export const useAddAllowForm = (onSuccess?: () => void, onClose?: () => void) => {
  const [formState, setFormState] = useState<FormState>({
    url: '',
    isValidUrl: false,
    loading: false,
    error: '',
    protectionOptions: createDefaultProtectionOptions()
  });

  const setUrl = useCallback((url: string) => {
    const isValid = validateUrl(url);
    setFormState(prev => ({
      ...prev,
      url,
      isValidUrl: isValid,
      error: ''
    }));
  }, []);

  const setError = useCallback((error: string) => {
    setFormState(prev => ({ ...prev, error }));
  }, []);

  const setLoading = useCallback((loading: boolean) => {
    setFormState(prev => ({ ...prev, loading }));
  }, []);

  const toggleProtection = useCallback((optionId: string) => {
    setFormState(prev => ({
      ...prev,
      protectionOptions: toggleProtectionOption(prev.protectionOptions, optionId)
    }));
  }, []);

  const resetForm = useCallback(() => {
    setFormState({
      url: '',
      isValidUrl: false,
      loading: false,
      error: '',
      protectionOptions: createDefaultProtectionOptions()
    });
  }, []);

  const validateForm = useCallback((): string | null => {
    if (!formState.isValidUrl) {
      return 'Please enter a valid domain or IP address';
    }

    const selectedProtections = getSelectedProtectionKeys(formState.protectionOptions);
    if (selectedProtections.length === 0) {
      return 'Please select at least one protection to disable';
    }

    return null;
  }, [formState.isValidUrl, formState.protectionOptions]);

  const submitForm = useCallback(async () => {
    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);
    setError('');

    try {
      const processedHost = processAllowListInput(formState.url);
      const selectedProtections = getSelectedProtectionKeys(formState.protectionOptions);
      const allowData = selectedProtections.join(',');

      const response = await sendBackgroundMessage({
        type: MSG_ADD_ALLOW,
        payload: { 
          host: processedHost, 
          allow: allowData, 
          fromAllowTab: true 
        }
      });

      if (response.error) {
        setError(response.error);
      } else {
        resetForm();
        onClose?.();
        onSuccess?.();
      }
    } catch (err) {
      setError('Failed to add website to allow list');
      console.error('Error adding allow item:', err);
    } finally {
      setLoading(false);
    }
  }, [formState.url, formState.protectionOptions, validateForm, onSuccess, onClose, setError, setLoading, resetForm]);

  const canSubmit = formState.isValidUrl && 
    formState.protectionOptions.some(opt => opt.selected) && 
    !formState.loading;

  return {
    formState,
    actions: {
      setUrl,
      setError,
      toggleProtection,
      resetForm,
      submitForm
    },
    computed: {
      canSubmit
    }
  };
};
