import React from 'react';
import { BGButton, BGSvgIcon, Card } from '$Popup/components/core';
import { cn } from '$Popup/lib/utils';
import { t } from '$Popup/i18n';
import { usePremiumStatus, useOperatingSystem } from '$Popup/utils/general';


interface UpgradeCardProps {
  className?: string,
  externalLink?: string
}

const UpgradeCard: React.FC<UpgradeCardProps> = ({
  className,
  externalLink
}) => {
  const { isPremium } = usePremiumStatus();
  const { os } = useOperatingSystem();

  externalLink = `${externalLink}_${os.toLowerCase()}`;
  
  if (isPremium) {
    return <></>;
  }

  return (
    <Card
      className={cn(
        'flex flex-col items-start justify-start py-8 px-6 gap-6 bg-backdrop-upspell-card',
        className
      )}
    >
      <div data-testid="div-cf96f0d8"  className="flex flex-row items-center justify-center gap-4">
        <div data-testid="div-50ece930"  className="flex flex-col items-start justify-center gap-2">
          <div data-testid="div-f507ba88"  className="title-large ">{t('mv3WebsiteBlockLevelUp')}</div>
          <p data-testid="p-be87da72" >
            {t('mv3WebsiteBlockLevelUpInfo')}{' '}
            <a data-testid="a-434e5062" 
              className={'text-primary font-medium cursor-pointer'}
              href={externalLink}
              target={'_blank'}
              rel={'noreferrer'}
            >
              {t('mv3WebsiteBlockLevelUpInfoLink')}
            </a>{' '}
            {t('mv3WebsiteBlockLevelUpInfoContd')}
          </p>
        </div>
        <BGSvgIcon iconName="mwb-logo-clouds" width={110} height={90} />
      </div>
      <BGButton variant="secondary" size={'small'} onClick={() => {window.open(externalLink, '_blank') }}>
        {t('mv3WebsiteBlockGetStarted')}
      </BGButton>
    </Card>
  );
}
export default UpgradeCard
